(function (L) {
  // ===== 中学地理 =====
  L.c_m1 = {
    goal: '緯度・経度で場所を表し、時差を計算できるようになり、世界の気候と各地域の特色を理由とセットで説明できるようになる。',
    intro: '地球は1日(24時間)で1回転しています。だから、日本が昼のとき、地球の反対側は夜です。この「場所によって時刻がちがう」しくみを数字で表したのが【時差】です。世界地理は、まず「地球上の住所」である緯度・経度を知り、そこから気候、さらに人々の暮らしや産業へとつなげていくと、ばらばらの暗記ではなくなります。',
    secs: [
      { h: '緯度・経度は地球の住所', t: '【緯度】は、赤道を0度として南北にそれぞれ90度まで測ります。北半球は北緯、南半球は南緯です。\n【経度】は、イギリスのロンドン(旧グリニッジ天文台)を通る【本初子午線】を0度として、東西にそれぞれ180度まで測ります。東側が東経、西側が西経です。\n地球には6つの大陸(ユーラシア・アフリカ・北アメリカ・南アメリカ・オーストラリア・南極)と、3つの大洋(太平洋・大西洋・インド洋)があります。世界で面積が最も大きい国はロシア、2番目はカナダです。' },
      { h: '時差は「15度で1時間」', t: '地球は24時間で360度回るので、360÷24=【15度】回ると1時間たちます。だから、経度が15度ちがうと時刻が1時間ずれます。\n日本の標準時は、兵庫県明石市を通る【東経135度】の経線で決めています。\n東へ行くほど太陽が早くのぼるので、時刻は【東ほど進んでいる】、西ほど遅れている、と考えます。\n計算の手順:①2地点の経度の差を出す(東経どうし・西経どうしは引き算、東経と西経なら足し算)。②15でわって時差を出す。③西にある地点なら時差を引き、東にある地点なら足す。\n日付は、ほぼ180度の経線にそって引かれた【日付変更線】で変わります。',
        ex: [
          { q: '日本(東経135度)が1月10日午後3時のとき、ロンドン(経度0度)は何日の何時?', steps: ['経度の差:135−0=135度。', '時差:135÷15=9時間。', 'ロンドンは日本より西にあるので、9時間遅れている。', '午後3時(15時)−9時間=6時。'], a: '1月10日午前6時' },
          { q: '日本(東経135度)が1月1日午前10時のとき、ニューヨーク(西経75度)は何日の何時?', steps: ['東経と西経なので足す:135+75=210度。', '時差:210÷15=14時間。', 'ニューヨークは西側なので14時間遅れている。', '10時−14時間=−4時 → 前の日の24−4=20時。'], a: '12月31日午後8時' }
        ] },
      { h: '世界の気候は5つに分けられる', t: '世界の気候は、気温と降水量によって大きく5つに分けられます。\n【熱帯】…赤道付近。1年中暑い。熱帯雨林やサバナが広がる。\n【乾燥帯】…雨が少ない。砂漠や、短い草が生えるステップ。\n【温帯】…四季がある。日本の大部分もここ。西ヨーロッパは、暖流(北大西洋海流)と【偏西風】のおかげで、高緯度のわりに冬が温暖(西岸海洋性気候)。地中海沿岸は夏に乾燥する(地中海性気候)。\n【冷帯(亜寒帯)】…冬の寒さがきびしい。針葉樹林(タイガ)が広がる。北半球にだけある。\n【寒帯】…1年中寒い。ツンドラや氷雪の世界。\n気候が分かると、「なぜその作物を育てるのか」「なぜその家の形なのか」が説明できるようになります。' },
      { h: '世界の諸地域は「自然→産業→課題」で整理する', t: '【アジア】…季節風(モンスーン)の影響で雨が多い地域では稲作がさかん。中国は沿岸部の【経済特区】から工業化が進んだ。インドはICT(情報通信技術)産業がのびている。東南アジアの国々はASEANで協力している。\n【ヨーロッパ】…多くの国が【EU(ヨーロッパ連合)】に加わり、共通通貨ユーロを使う国も多い。課題は加盟国間の経済格差。\n【アフリカ】…ヨーロッパの植民地だった歴史から、経線・緯線にそった直線の国境が多い。特定の農産物や鉱産資源の輸出にたよる【モノカルチャー経済】の国が多く、価格の変動に経済が左右されやすい。\n【北アメリカ】…アメリカ合衆国は、土地の気候に合った作物を大規模に育てる【適地適作】。北緯37度より南の【サンベルト】で先端技術産業が発達。\n【南アメリカ】…アマゾン川流域の熱帯林の減少が課題。ブラジルはさとうきびから【バイオエタノール】をつくる。\n【オセアニア】…オーストラリアは鉄鉱石・石炭などの鉱産資源が豊富。かつての白豪主義をやめ、今は多文化社会をめざしている。' }
    ],
    terms: [['本初子午線', 'ロンドンを通る経度0度の経線'], ['標準時子午線', 'その国の時刻の基準にする経線。日本は東経135度'], ['日付変更線', 'ほぼ180度の経線にそって引かれ、ここを越えると日付が変わる線'], ['偏西風', '中緯度の上空を、1年中西から東へふく風'], ['モノカルチャー経済', '特定の農産物や鉱産資源の生産・輸出にたよる経済']],
    miss: ['西にある国の時刻を「進んでいる」と考えてしまう(西ほど遅れている)。', '東経と西経の地点の時差で、経度を足さずに引いてしまう。', '時刻が0時をまたぐのに、日付を変え忘れる。'],
    sum: ['緯度は赤道が0度、経度はロンドンが0度。', '経度15度で1時間の時差。東ほど時刻が進んでいる。', '気候は熱帯・乾燥帯・温帯・冷帯・寒帯の5つ。', '各地域は「自然 → 産業 → 課題」の順に、理由をつけて覚える。']
  };

  L.c_jgeo = {
    goal: '日本の位置と領域、地形と気候の特色を理由とともに説明でき、各地方の産業の特色を整理できるようになる。',
    intro: '日本は南北に長く、山が多く、まわりを海に囲まれた国です。この3つの特徴だけで、「なぜ日本海側は冬に雪が多いのか」「なぜ扇状地に果樹園が多いのか」など、たくさんのことが説明できます。地名は、白地図に書きこみながら場所とセットで覚えると忘れにくくなります。',
    secs: [
      { h: '日本の位置と領域', t: '日本はユーラシア大陸の東にある島国で、およそ北緯20〜46度、東経122〜154度の範囲にあります。面積は約38万km²です。\n日本の端:北端は【択捉島】、南端は【沖ノ鳥島】、東端は【南鳥島】、西端は【与那国島】です。\n国の領域は、領土・【領海】(海岸線から12海里)・領空からなります。さらに海岸線から200海里(約370km)までの【排他的経済水域】では、水産資源や鉱産資源を自分の国のものとして利用できます。日本は島が多いので、国土面積のわりにこの水域がとても広い国です。沖ノ鳥島で護岸工事をしたのは、島が波でけずられて水域を失わないようにするためです。\n領土をめぐる問題:【北方領土】(歯舞群島・色丹島・国後島・択捉島)はロシアが占拠しています。【竹島】(島根県)は韓国が不法に占拠しています。【尖閣諸島】(沖縄県)は日本が有効に支配していますが、中国などが領有を主張しています。' },
      { h: '地形:山がちで、川は短く急', t: '日本は国土の約4分の3が山地です。そのため川は短く、流れが急です。\n川が山から平地に出るところには、土砂が扇の形に積もった【扇状地】ができます。つぶの大きい砂やれきでできていて水はけがよいので、【果樹園】に利用されることが多いです(例:山梨県の甲府盆地)。\n川が海に流れこむ河口には、細かい土砂が積もった【三角州】ができます。低く平らで水が得やすいので、水田や都市に利用されます(例:広島市)。\n海岸には、山地が海にしずんでできた、入り組んだ【リアス海岸】(例:三陸海岸・志摩半島)があり、波がおだやかなので養殖業がさかんです。',
        ex: [{ q: '扇状地が水田より果樹園に利用されやすいのはなぜ?', steps: ['扇状地は、川が山から出たところで、つぶの大きい砂やれきが積もってできる。', 'つぶが大きいとすき間が多く、水がしみこみやすい(水はけがよい)。', '水田は水をためる必要があるので向かない。水はけのよい土地は果樹の栽培に向く。'], a: '砂やれきでできていて水はけがよく、水をためる水田には向かないが、果樹の栽培には適しているから。' }] },
      { h: '気候:季節風が決め手', t: '日本の大部分は温帯ですが、季節によって向きが変わる【季節風(モンスーン)】の影響で、地域ごとに気候がちがいます。\n【日本海側】…冬に北西の季節風が日本海で水分をふくみ、山地にぶつかって大雪をふらせる。冬の降水量が多い。\n【太平洋側】…夏に南東の季節風がふき、夏の降水量が多い。冬は乾燥して晴れが多い。\n【中央高地(内陸)】…山に囲まれ、季節風がさえぎられるので降水量が少ない。夏と冬の気温差が大きい。\n【瀬戸内】…中国山地と四国山地が両方の季節風をさえぎるので、1年中降水量が少ない。水不足に備えてため池がつくられてきた。\n【北海道】…冬の寒さがきびしい冷帯。はっきりした梅雨がない。\n【南西諸島】…1年中温暖で降水量が多い。台風の通り道。',
        ex: [{ q: 'ある都市の雨温図では、12〜2月の降水量が1年でいちばん多い。この都市は日本のどの気候区に属すると考えられる?', steps: ['冬に降水量(雪)が多いのはどこかを考える。', '冬の北西季節風が日本海で水分をふくみ、山地にぶつかって雪をふらせる。', 'それが起きるのは日本海側。'], a: '日本海側の気候' }] },
      { h: '各地方の特色(産業と理由)', t: '【九州】…南部には火山灰が積もった【シラス台地】が広がり、水もちが悪いので稲作に向かず、畜産(ぶた・肉牛・にわとり)や茶・さつまいもの栽培がさかん。\n【中国・四国】…瀬戸内工業地域で石油化学工業。本州四国連絡橋で行き来が便利になった。\n【近畿】…阪神工業地帯。京都・奈良には古い町なみや文化財が多い。\n【中部】…【中京工業地帯】は自動車などの輸送用機械が中心で、出荷額が全国最大。中央高地では高原の夏のすずしさを生かした野菜づくり。\n【関東】…東京を中心に人口が集中。大消費地に近い利点を生かした【近郊農業】。\n【東北】…夏に冷たくしめった北東の風【やませ】がふくと、太平洋側で冷害が起きやすい。米の大産地。\n【北海道】…根釧台地などで【酪農】、石狩平野で稲作、十勝平野で畑作。' }
    ],
    terms: [['排他的経済水域', '海岸線から200海里までの、資源を沿岸国が利用できる水域'], ['扇状地', '川が山から平地に出るところに土砂が積もった、扇形の地形'], ['三角州', '河口付近に細かい土砂が積もってできた低く平らな地形'], ['季節風(モンスーン)', '夏と冬で向きが変わる風。夏は南東、冬は北西からふく'], ['やませ', '東北地方の太平洋側に夏にふく、冷たくしめった北東の風'], ['近郊農業', '大都市の近くで、新鮮さを生かして野菜などを出荷する農業']],
    miss: ['扇状地と三角州の場所(山のふもとか、河口か)を逆に覚える。', '日本海側の雪の原因を「日本海側が寒いから」と答え、季節風と山地を書き忘れる。', '排他的経済水域を「領海」と混同する(排他的経済水域は他国の船も通れる)。'],
    sum: ['日本の端は択捉島・沖ノ鳥島・南鳥島・与那国島。', '扇状地は果樹園、三角州は水田や都市。理由は水はけ。', '気候は季節風と山地の位置で説明する。', '各地方の産業は「自然条件 → だから何がさかんか」で覚える。']
  };

  var CONTOUR = '<svg viewBox="0 0 220 150" class="lz-fig" role="img" aria-label="等高線の間隔と土地の傾き"><ellipse cx="110" cy="55" rx="80" ry="45" class="cv"/><ellipse cx="100.5" cy="55" rx="64.5" ry="35" class="cv"/><ellipse cx="91" cy="55" rx="49" ry="25" class="cv"/><ellipse cx="81.5" cy="55" rx="33.5" ry="15" class="cv"/><circle cx="74" cy="55" r="3" class="pt"/><text x="80" y="59">山頂</text><text x="192" y="58">10</text><text x="167" y="58">20</text><text x="142" y="58">30</text><text x="117" y="58">40</text><text x="8" y="124">左:間隔がせまい→急な斜面</text><text x="8" y="140">右:間隔が広い→ゆるやかな斜面(m)</text></svg>';

  L.c_chizu = {
    goal: '地形図の縮尺から実際の距離を計算し、等高線と地図記号から土地のようすを読み取れるようになる。',
    intro: '地形図は、本物の土地を小さく縮めて、決まった記号で表した「土地の設計図」です。縮尺が分かれば地図上の長さから実際の距離が出せ、等高線が読めれば山の高さや斜面の急さまで分かります。計算は「cm → m → km」の単位の直し方さえ気をつければむずかしくありません。',
    secs: [
      { h: '縮尺と実際の距離', t: '【縮尺】は、実際の距離をどれだけ縮めたかを表します。2万5千分の1なら、実際の距離を25000分の1にしています。\n【実際の距離=地図上の長さ×縮尺の分母】\n単位の直し方:100cm=1m、1000m=1km、つまり 100000cm=1km です。\n2万5千分の1の地形図では、4cmが1kmにあたります(4×25000=100000cm)。\n地図には、方位記号がなければ上が北です。',
        ex: [
          { q: '2万5千分の1の地形図で、2点間の長さが6cmだった。実際の距離は何km?', steps: ['実際の距離=6×25000=150000cm。', '100cm=1m なので 150000cm=1500m。', '1000m=1km なので 1500m=1.5km。'], a: '1.5km' },
          { q: '実際の距離が2.5kmの道は、5万分の1の地形図上では何cmになる?', steps: ['2.5km=2500m=250000cm。', '地図上の長さ=実際の距離÷縮尺の分母。', '250000÷50000=5。'], a: '5cm' }
        ] },
      { h: '等高線の読み方', t: '【等高線】は、同じ高さの地点を結んだ線です。\n2万5千分の1の地形図では、細い【主曲線】が10mごと、太い【計曲線】が50mごとに引かれます(5万分の1では主曲線20mごと、計曲線100mごと)。\n等高線の【間隔がせまい】ところは、少し進むだけで高さが大きく変わるので【傾きが急】です。間隔が広いところは傾きがゆるやかです。\n等高線が、低い方へ張り出しているところは【尾根】、高い方へ食いこんでいるところは【谷】です。谷には川ができやすくなります。',
        fig: CONTOUR,
        ex: [{ q: '2万5千分の1の地形図で、ある地点は計曲線(太い線)の150mの線上にある。そこから山頂側へ細い線を2本こえた地点の標高は?', steps: ['2万5千分の1の主曲線(細い線)は10mごと。', '山頂側へ1本こえると160m、2本こえると170m。'], a: '170m' }] },
      { h: 'おもな地図記号', t: '地図記号は、そのものの形や、関係する道具・文字をもとにつくられています。\n土地利用:【田】は稲をかりとったあとの形(||)、【畑】は植物の双葉の形(V)、【果樹園】は果実の形、【茶畑】は茶の実の形(∴)、広葉樹林・針葉樹林は木の形です。\n建物・施設:【小・中学校】は「文」の字、【郵便局】は〒のマーク、【警察署】は⊗、【交番】は×、【消防署】は昔の消火道具(さすまた)の形、【寺院】は卍、【神社】は鳥居の形、【市役所】は◎、町村役場は○。\n新しい記号:【老人ホーム】(建物の中につえ)、【図書館】(本を開いた形)、【博物館】(建物の形)、自然災害の教訓を伝える【自然災害伝承碑】などがあります。' },
      { h: '地形図から土地のようすを読む', t: '地形図の問題は、等高線と地図記号を組み合わせて読みます。\n例1:等高線の間隔が広く、平らなところに田の記号が多い → 川ぞいの低地で、水が得やすい。\n例2:山のふもとの扇形に広がる土地に果樹園の記号が多い → 扇状地。\n面積の計算は、たて・よこの実際の長さをそれぞれ出してからかけます。2万5千分の1で2cm×2cmの正方形なら、実際は500m×500m=250000m²=0.25km²です(長さを先に直すのがポイント)。' }
    ],
    terms: [['縮尺', '実際の距離を地図上でどれだけ縮めたかを表す割合'], ['等高線', '同じ高さの地点を結んだ線'], ['主曲線・計曲線', '細い線と太い線の等高線。2万5千分の1では10mごと・50mごと'], ['尾根', '等高線が低い方へ張り出した、山の高い部分の連なり'], ['谷', '等高線が高い方へ食いこんだ部分。川ができやすい']],
    miss: ['cm を km に直すとき、0の数をまちがえる(100000cm=1km)。', '等高線の間隔がせまい=ゆるやか、と逆に覚える。', '2万5千分の1と5万分の1で、等高線の間隔(10mと20m)を取りちがえる。', '面積を「地図上の面積×25000」で計算してしまう(長さを先に直す)。'],
    sum: ['実際の距離=地図上の長さ×縮尺の分母。', '2万5千分の1では4cm=1km、主曲線10m・計曲線50m。', '等高線の間隔がせまいほど急な斜面。', '地図記号は形のもとになったものと結びつけて覚える。']
  };

  // ===== 中学歴史 =====
  L.c_ancient = {
    goal: '古代文明の誕生から、律令国家の成立、貴族の政治へと移る流れを、原因と結果で説明できるようになる。',
    intro: '古代の歴史は、「ムラがクニになり、クニが国家になる」物語です。米づくりが始まると、たくわえや土地をめぐって争いが起き、強い者が人々をまとめるようになります。やがて中国にならった法律(律令)で国を治めるしくみができ、そのしくみがゆらいで貴族が力をもつ時代へと進みます。',
    secs: [
      { h: '人類の出現と古代文明', t: '人類は打製石器を使い、狩りや採集をして暮らしていました(旧石器時代)。やがて農耕や牧畜が始まり、大きな川のほとりで文明が生まれます。\n【エジプト文明】(ナイル川)…ピラミッド、象形文字。\n【メソポタミア文明】(チグリス川・ユーフラテス川)…くさび形文字、太陰暦。\n【インダス文明】(インダス川)…計画的な都市(モヘンジョ=ダロ)。\n【中国文明】(黄河)…甲骨文字。のちに秦の始皇帝が中国を統一。\n大河の近くで文明が生まれたのは、水が得やすく土地が肥えていて、農耕で多くの人を養えたからです。' },
      { h: '縄文・弥生・古墳時代', t: '【縄文時代】…縄目の文様の土器を使い、たて穴住居に住み、狩り・漁・採集で暮らした。貝塚が残る。\n【弥生時代】…大陸から【稲作】と金属器(青銅器・鉄器)が伝わった。米をたくわえられるようになると、貧富の差や身分の差が生まれ、土地や水をめぐる争いからムラがまとまってクニができた。3世紀には【卑弥呼】が治める邪馬台国があったと、中国の歴史書(「魏志」倭人伝)に書かれています。\n【古墳時代】…大王を中心とする【大和政権(ヤマト王権)】が各地の豪族を従えた。大きな前方後円墳は、強い力をもつ支配者がいたことを示します。' },
      { h: '天皇中心の国づくり(飛鳥・奈良時代)', t: '【聖徳太子】(厩戸皇子)は、蘇我馬子と協力して、家がらではなく能力で役人を選ぶ冠位十二階や、役人の心がまえを示す十七条憲法を定め、遣隋使を送りました。\n645年、【中大兄皇子】と【中臣鎌足】が蘇我氏を倒し、【大化の改新】を始めました。土地と人々を国のものにする【公地公民】をめざします。\n701年の【大宝律令】で、律(刑罰のきまり)と令(政治のきまり)による国家のしくみが整い、710年に都が【平城京】(奈良)に移りました。\n人々には6歳以上の男女に【口分田】が与えられ(班田収授法)、租・調・庸などの税や兵役が課されました。聖武天皇は仏教の力で国を守ろうとし、東大寺の大仏や国分寺をつくらせました。',
        ex: [{ q: '次のできごとを古い順に並べよう。ア 平安京に都を移す イ 大化の改新 ウ 平城京に都を移す エ 大宝律令の制定', steps: ['大化の改新は645年。国づくりの出発点。', '大宝律令は701年。法律のしくみが整う。', '平城京は710年。律令にもとづく都。', '平安京は794年。'], a: 'イ → エ → ウ → ア' }] },
      { h: '律令のゆらぎと貴族の政治(平安時代)', t: '人口がふえて口分田が足りなくなると、国は開墾をすすめるため、743年に【墾田永年私財法】を出し、新しく開いた土地の永久の私有を認めました。その結果、貴族や寺社が私有地を広げ、のちの【荘園】のもとになります。これは公地公民の原則がくずれていくことを意味しました。\n794年、【桓武天皇】が都を【平安京】(京都)に移し、政治の立て直しをはかりました。\nその後、【藤原氏】が娘を天皇のきさきにし、生まれた子を天皇に立てて、摂政・関白として政治の実権をにぎりました(【摂関政治】)。藤原道長・頼通のころが全盛期です。\n遣唐使が停止されると(894年、菅原道真の進言)、日本の風土に合った【国風文化】が発達し、かな文字が生まれ、紫式部の「源氏物語」や清少納言の「枕草子」が書かれました。',
        ex: [{ q: '墾田永年私財法が出されたことで、土地のしくみはどう変わった?原因と結果で説明しよう。', steps: ['原因:人口がふえ、口分田が不足していた。', '国は開墾をすすめるため、新しく開いた土地の永久私有を認めた。', '結果:貴族や寺社が開墾して私有地を広げ、荘園が生まれた。', 'まとめ:土地も人も国のものという公地公民の原則がくずれた。'], a: '口分田の不足を補うために開墾地の永久私有を認めた結果、貴族や寺社の私有地(荘園)が広がり、公地公民の原則がくずれていった。' }] }
    ],
    terms: [['大和政権', '大王を中心に、近畿地方の豪族がつくった政権'], ['律令', '律は刑罰のきまり、令は政治のきまり。中国(唐)にならった'], ['公地公民', '土地と人々を国(天皇)のものとする原則'], ['墾田永年私財法', '743年。新しく開墾した土地の永久私有を認めた法'], ['摂関政治', '藤原氏が摂政・関白となって行った政治'], ['国風文化', '平安時代中ごろの、日本の風土や生活に合った文化']],
    miss: ['平城京(710年・奈良)と平安京(794年・京都)を取りちがえる。', '墾田永年私財法を「土地を国のものにした法」と逆に覚える。', '摂関政治を天皇自身が行った政治と思ってしまう(実権は藤原氏)。'],
    sum: ['稲作が始まり、ムラ → クニ → 大和政権へとまとまった。', '大化の改新(645年)から大宝律令(701年)で律令国家ができた。', '墾田永年私財法(743年)で私有地が広がり、荘園が生まれた。', '平安時代は藤原氏の摂関政治と国風文化。']
  };

  L.c_medieval = {
    goal: '武士がおこり、鎌倉幕府・室町幕府が成立して戦国時代に至る流れを、原因と結果でつないで説明できるようになる。',
    intro: '中世は「武士が政治の主役になる時代」です。はじめは貴族のボディーガードにすぎなかった武士が、力をつけて幕府を開き、やがて全国を支配します。ポイントは、鎌倉と室町で「だれが・どこで・どのように」支配したかを比べることと、幕府がおとろえた原因をたどることです。',
    secs: [
      { h: '武士のおこりと平氏の政治', t: '地方で土地を守るために武装した人々が【武士】になり、源氏と平氏が二大勢力に成長しました。\n1086年、【白河上皇】が天皇の位をゆずったあとも上皇として政治を行う【院政】を始めます。\n保元の乱・平治の乱で勝った【平清盛】は、武士として初めて太政大臣になり、宋との貿易(日宋貿易)で富をたくわえました。しかし平氏が一族で高い位を独占したため、貴族や他の武士の反発をまねき、1185年、壇ノ浦の戦いで源氏にほろぼされました。' },
      { h: '鎌倉幕府と御恩・奉公', t: '【源頼朝】は1185年に国ごとに【守護】、荘園・公領に【地頭】を置くことを認めさせ、1192年に征夷大将軍になりました。\n幕府と武士(【御家人】)は、【御恩と奉公】という土地を仲立ちにした関係で結ばれていました。御恩=将軍が領地を守ったり新しく与えたりすること。奉公=御家人が戦いのときに命をかけて戦うこと。\n頼朝の死後は、北条氏が【執権】として実権をにぎりました。\n1221年、後鳥羽上皇が幕府を倒そうと兵をあげた【承久の乱】で幕府が勝ちます。幕府は京都に【六波羅探題】を置いて朝廷を監視し、上皇方の土地を御家人に与えたので、幕府の力が西日本にまで広がりました。\n1232年、執権【北条泰時】が、武士の裁判の基準として【御成敗式目】を定めました。' },
      { h: '元寇と鎌倉幕府のほろび', t: 'モンゴル帝国(元)のフビライ・ハンが日本を従えようとし、執権【北条時宗】がこれを退けると、元軍が2度攻めてきました(1274年文永の役、1281年弘安の役=【元寇】)。\n御家人は必死に戦いましたが、これは外国から守る戦いだったので、新しく得た土地がなく、幕府は十分な恩賞(御恩)を与えられませんでした。\nもともと分割相続で領地が小さくなっていた御家人は生活が苦しくなり、幕府は1297年に借金を帳消しにする【徳政令】を出しましたが、かえって経済が混乱しました。\nこうして御恩と奉公の関係がくずれ、幕府への不満が高まります。【後醍醐天皇】が足利尊氏・新田義貞らの協力を得て、1333年に鎌倉幕府はほろびました。',
        ex: [{ q: '元寇のあと、鎌倉幕府がおとろえたのはなぜ?因果の流れで説明しよう。', steps: ['元寇は防衛の戦いで、敵から奪った土地がなかった。', 'そのため幕府は御家人に十分な恩賞(土地)を与えられなかった。', '御家人は戦いの費用や分割相続で生活が苦しくなり、徳政令も効果がうすかった。', '御恩と奉公の関係がくずれ、幕府への不満が高まった。'], a: '元寇で恩賞の土地が与えられず、御家人が生活に苦しんで幕府への不満を強め、御恩と奉公の関係がくずれたから。' }] },
      { h: '室町幕府と戦国時代', t: '後醍醐天皇の【建武の新政】は、公家を重んじたため武士の不満をまねき、2年ほどでくずれました。【足利尊氏】は京都に別の天皇を立て、征夷大将軍になって幕府を開きます。後醍醐天皇は吉野にのがれ、朝廷が2つに分かれた【南北朝時代】が約60年続きました。\n3代将軍【足利義満】は1392年に南北朝を統一し、明と【勘合貿易(日明貿易)】を始めました。勘合という証明書を使ったのは、正式な貿易船と海賊(倭寇)を区別するためです。義満は京都の北山に【金閣】を建てました。\n室町幕府では、守護が力をつけて【守護大名】となりました。8代将軍【足利義政】のあとつぎ問題などから、1467年に【応仁の乱】が起き、京都は焼け野原になります。幕府の力は失われ、下の身分の者が上の者を実力で倒す【下剋上】の風潮が広がり、各地で【戦国大名】が争う戦国時代になりました。\n文化:義政は東山に【銀閣】を建て、たたみやふすまを使う【書院造】が広まりました。観阿弥・世阿弥が【能】を大成しました。',
        ex: [{ q: '次のできごとを古い順に並べよう。ア 元寇 イ 御成敗式目の制定 ウ 承久の乱 エ 永仁の徳政令', steps: ['承久の乱(1221年)で幕府が朝廷に勝つ。', 'その後、武士の裁判の基準として御成敗式目(1232年)。', '元寇(1274年・1281年)で御家人が疲れる。', '御家人を救うために徳政令(1297年)。'], a: 'ウ → イ → ア → エ' }] }
    ],
    terms: [['院政', '天皇が位をゆずったあとも、上皇として行う政治'], ['御恩と奉公', '将軍と御家人の、土地を仲立ちにした主従関係'], ['執権', '鎌倉幕府で将軍を補佐する役職。北条氏が独占した'], ['御成敗式目', '1232年に北条泰時が定めた、武士の裁判の基準'], ['勘合貿易', '勘合という証明書を使って行った明との貿易'], ['下剋上', '下の身分の者が、実力で上の者を倒すこと']],
    miss: ['承久の乱の結果を「朝廷が勝った」と逆に覚える(勝ったのは幕府)。', '元寇で幕府がおとろえた理由を「戦いに負けたから」と答える(撃退したが恩賞がなかった)。', '金閣(義満・北山)と銀閣(義政・東山)を取りちがえる。'],
    sum: ['鎌倉幕府は御恩と奉公でなりたち、北条氏が執権として支配した。', '承久の乱で幕府の力が西日本に広がった。', '元寇で恩賞が出せず、御恩と奉公がくずれて幕府はほろんだ。', '室町幕府は応仁の乱で力を失い、下剋上の戦国時代へ。']
  };

  L.c_early = {
    goal: '天下統一から江戸幕府の安定、三大改革、そして幕府のゆらぎまでの流れを「だれが・何を・なぜ」で説明できるようになる。',
    intro: '近世は、戦国の争いが終わって、長く平和が続いた時代です。織田信長・豊臣秀吉が全国を統一し、徳川家康が260年以上続く江戸幕府を開きました。平和が長く続いた理由(大名をおさえるしくみ)と、時代が進むにつれて出てきた問題(幕府の財政難)に、それぞれの改革がどう取り組んだかをつかみましょう。',
    secs: [
      { h: 'ヨーロッパ人の来航と天下統一', t: '1543年、種子島に流れ着いたポルトガル人が【鉄砲】を伝えました。1549年には【ザビエル】がキリスト教を伝えます。\n【織田信長】…1573年に室町幕府をほろぼし、1575年の長篠の戦いで鉄砲を有効に使って勝利。安土城の城下で【楽市・楽座】を行い、座の特権をなくして商工業をさかんにしました。1582年、本能寺の変でたおれます。\n【豊臣秀吉】…1590年に全国を統一。【太閤検地】で全国の田畑の広さや収穫量(石高)を調べ、耕す農民を検地帳に登録しました。1588年の【刀狩】で農民から武器を取り上げ、武士と農民の身分を分けました(【兵農分離】)。また、朝鮮に2度兵を送りましたが、失敗しました。' },
      { h: '江戸幕府のしくみ', t: '【徳川家康】は1600年の【関ヶ原の戦い】に勝ち、1603年に征夷大将軍となって江戸幕府を開きました。\n幕府は大名を、徳川家の親類(親藩)、もとからの家臣(譜代大名)、関ヶ原のころから従った(外様大名)に分け、外様大名は江戸から遠い場所に置きました。\n【武家諸法度】で大名に城の修理や大名どうしの勝手な結婚を禁じ、3代将軍【徳川家光】は【参勤交代】を制度にしました。大名は1年おきに江戸と領地を行き来し、妻子は江戸に住まわせられました。\nこのように幕府と藩が土地と人々を支配するしくみを【幕藩体制】といいます。',
        ex: [{ q: '参勤交代のねらいと、その結果どうなったかを説明しよう。', steps: ['ねらい:大名に江戸との往復や江戸での生活の費用を使わせ、将軍への忠誠を示させた。', 'その結果、大名は経済的に負担が大きくなり、幕府に反抗する力をたくわえにくくなった。', '一方で、大名行列が通る街道や宿場町が発達し、江戸と地方の文化の交流も進んだ。'], a: '大名を江戸と領地に往復させて費用を使わせ、幕府に従わせるため。その結果、大名の力がおさえられ、街道や宿場町が発達した。' }] },
      { h: '鎖国:なぜ国を閉じたのか', t: '幕府は、キリスト教の信者が団結して幕府に従わなくなることをおそれ、キリスト教を禁止しました。1637年、重い年貢とキリスト教の取りしまりに苦しんだ人々が【島原・天草一揆】を起こすと、幕府はさらに取りしまりを強め、1639年にポルトガル船の来航を禁止、1641年にはオランダ商館を長崎の【出島】に移しました。これを【鎖国】といいます。\nただし、まったく国を閉じたわけではなく、【長崎】(オランダ・中国)、【対馬藩】(朝鮮)、【薩摩藩】(琉球王国)、【松前藩】(蝦夷地のアイヌの人々)の4つの窓口で交流が続きました。オランダが貿易を許されたのは、キリスト教を広めなかったからです。' },
      { h: '幕府の財政難と三大改革', t: '平和が続いて商業が発達すると、米を収入の中心とする幕府や武士の生活は苦しくなりました。そこで改革が行われます。\n【享保の改革】(8代将軍 徳川吉宗)…質素・倹約、新田開発、大名に米を納めさせる上げ米、裁判の基準となる公事方御定書、庶民の意見を聞く目安箱。\n【田沼意次の政治】…商人の力を利用し、株仲間を奨励して税を取った。わいろが広がったと批判され、天明のききんも重なって失脚。\n【寛政の改革】(老中 松平定信)…ききんに備えて米をたくわえさせ、旗本・御家人の借金を帳消しにし、朱子学以外の学問を幕府の学校で教えることを禁じた。\n【天保の改革】(老中 水野忠邦)…物価を下げるため株仲間を解散させたが、きびしすぎて反発をまねき、2年余りで失敗。\n文化:上方(大阪・京都)の町人が中心の【元禄文化】(井原西鶴・近松門左衛門・松尾芭蕉)と、江戸の町人が中心の【化政文化】(葛飾北斎・歌川広重の浮世絵)。',
        ex: [{ q: '次の政治を古い順に並べよう。ア 天保の改革 イ 田沼意次の政治 ウ 享保の改革 エ 寛政の改革', steps: ['享保の改革は8代将軍吉宗(18世紀前半)。', '田沼意次の商業重視の政治(18世紀後半)。', '田沼の政治を引きしめ直したのが松平定信の寛政の改革。', '19世紀前半に水野忠邦の天保の改革。'], a: 'ウ → イ → エ → ア' }] }
    ],
    terms: [['太閤検地', '豊臣秀吉が行った全国の田畑の調査。石高で土地を表した'], ['兵農分離', '刀狩などで、武士と農民の身分を分けたこと'], ['参勤交代', '大名が1年おきに江戸と領地を行き来した制度'], ['鎖国', 'キリスト教禁止と貿易統制のため、外国との交流を制限した体制'], ['株仲間', '商工業者の同業者組合。田沼は奨励し、水野は解散させた']],
    miss: ['参勤交代を始めたのを家康と答える(制度にしたのは家光)。', '鎖国で「どこの国とも交流しなかった」と思う(4つの窓口があった)。', '株仲間を「奨励した田沼」と「解散させた水野」を逆に覚える。'],
    sum: ['信長・秀吉が統一し、太閤検地と刀狩で兵農分離が進んだ。', '江戸幕府は大名配置・武家諸法度・参勤交代で大名をおさえた。', '鎖国はキリスト教禁止と貿易の独占のため。窓口は4つ。', '改革の順は 享保 → 田沼 → 寛政 → 天保。']
  };

  L.c_modern = {
    goal: '開国から明治維新、条約改正、日清・日露戦争、大正デモクラシー、第二次世界大戦までの流れを、因果でつないで説明できるようになる。',
    intro: '近代は、日本が「欧米に追いつけ」と、短い期間で国のしくみを大きく変えた時代です。開国で不平等な条約を結ばされたことが出発点になり、「条約を対等にするには、欧米なみの強い近代国家にならなければ」という目標が、明治の改革や戦争を動かしました。できごとを「目標に向かって何をしたか」という1本の線でつなぎましょう。',
    secs: [
      { h: '開国と江戸幕府のおわり', t: '1853年、アメリカの【ペリー】が浦賀に来航し、開国を求めました。翌1854年の【日米和親条約】で下田・函館を開港します。\n1858年、大老【井伊直弼】は朝廷の許可を得ないまま【日米修好通商条約】を結びました。この条約は、外国人が日本で罪をおかしても日本の法律で裁けない【領事裁判権(治外法権)】を認め、日本に輸入品の関税を自由に決める【関税自主権】がない、【不平等条約】でした。\n開国で物価が上がり、天皇を尊び外国を追いはらおうとする【尊王攘夷運動】が高まります。しかし、外国と戦って力の差を知った薩摩藩と長州藩は、倒幕へと方針を変え、1866年に坂本龍馬らの仲立ちで【薩長同盟】を結びました。\n1867年、15代将軍【徳川慶喜】は政権を朝廷に返す【大政奉還】を行い、朝廷は【王政復古の大号令】を出して天皇中心の新政府をつくりました。' },
      { h: '明治維新:近代国家のしくみづくり', t: '新政府は1868年に【五箇条の御誓文】で政治の方針を示しました。\n【版籍奉還】(1869年)で藩の土地と人民を天皇に返させ、【廃藩置県】(1871年)で藩をなくして府県を置き、中央から府知事・県令を送りました。これで全国を政府が直接治められるようになります。\n【富国強兵】のための三大改革:学制(1872年・6歳以上の男女に教育)、【徴兵令】(1873年・満20歳以上の男子に兵役)、【地租改正】(1873年)。\n地租改正では、土地の所有者に地券を発行し、収穫高ではなく【地価の3%】を【現金】で納めさせました。米の収穫は豊作・不作で変わりますが、地価を基準にすれば毎年決まった税収が入ります。ねらいは【国の財政を安定させること】でした。\n【殖産興業】として官営の富岡製糸場などをつくり、産業をおこしました。',
        ex: [{ q: '地租改正で、税のしくみはどう変わった?また、そのねらいは?', steps: ['変わる前:収穫高に応じて、主に米で年貢を納めていた。', '変わった後:土地の所有者が、地価の3%を現金で納める。', '米の量は年によって変わるが、地価を基準にした現金なら毎年同じ額が入る。'], a: '収穫高に応じた米の年貢から、地価の3%を土地所有者が現金で納める税に変わった。ねらいは、国の税収を安定させること。' }] },
      { h: '立憲国家と条約改正', t: '1874年、板垣退助らが国会を開くよう求める民撰議院設立の建白書を出し、【自由民権運動】が始まりました。政府は1881年に国会を開くことを約束します。\n【伊藤博文】は、君主の権力が強いドイツ(プロイセン)の憲法を学び、1889年に【大日本帝国憲法】が発布されました。主権は天皇にありました。1890年には第1回帝国議会が開かれ、日本は憲法と議会をもつ立憲国家になりました。\n憲法と議会が整ったことで、欧米に「近代国家」と認められやすくなり、条約改正が進みました。1894年に外務大臣【陸奥宗光】が領事裁判権の撤廃に成功し、1911年に【小村寿太郎】が関税自主権を完全に回復しました。' },
      { h: '日清・日露戦争と大正デモクラシー', t: '朝鮮をめぐって清と対立し、1894年に【日清戦争】が起こりました。勝った日本は【下関条約】(1895年)で賠償金と台湾・遼東半島などを得ましたが、ロシア・ドイツ・フランスの【三国干渉】で遼東半島を返しました。\nロシアへの対抗から、1902年に【日英同盟】を結び、1904年に【日露戦争】が起こります。【ポーツマス条約】(1905年)で南樺太などを得ましたが、賠償金が取れなかったため、重い税にたえてきた国民が不満を爆発させ、日比谷焼き打ち事件が起きました。1910年、日本は韓国を併合しました。\n1914年に【第一次世界大戦】が始まると、日本は日英同盟を理由に参戦し、輸出がのびて好景気になりました。一方で物価が上がり、1918年に米の値上がりに怒った人々が【米騒動】を起こすと、【原敬】が初めての本格的な政党内閣をつくりました。\n吉野作造の民本主義などで民主主義を求める動きが広がり(【大正デモクラシー】)、1925年に満25歳以上のすべての男子に選挙権を与える【普通選挙法】が成立しました。同じ年、社会主義などを取りしまる【治安維持法】も定められました。',
        ex: [{ q: '次のできごとを古い順に並べよう。ア 日英同盟 イ 三国干渉 ウ 韓国併合 エ 日露戦争', steps: ['日清戦争の講和(下関条約、1895年)の直後に三国干渉。', 'ロシアの南下に対抗するため、日英同盟(1902年)。', 'その2年後に日露戦争(1904年)。', '日露戦争で韓国への優越権を得て、韓国併合(1910年)。'], a: 'イ → ア → エ → ウ' }] },
      { h: '世界恐慌から第二次世界大戦へ', t: '1929年、アメリカから【世界恐慌】が広がり、日本も深刻な不景気になりました。\n不景気からぬけ出す道を中国東北部(満州)に求めた軍(関東軍)は、1931年に【満州事変】を起こし、翌年に満州国をつくります。国際連盟がこれを認めなかったため、日本は1933年に【国際連盟を脱退】し、国際的に孤立していきました。\n国内では1932年の五・一五事件(犬養毅首相が暗殺)、1936年の二・二六事件などで軍部の力が強まり、政党政治が終わりました。\n1937年に【日中戦争】が始まり、1938年には国家総動員法で国民や物資を戦争に動員できるようにしました。1939年にドイツのポーランド侵攻で【第二次世界大戦】が始まり、日本は1940年に日独伊三国同盟を結び、1941年12月、ハワイの真珠湾などを攻撃して【太平洋戦争】が始まりました。\n1945年8月、広島(6日)・長崎(9日)に原子爆弾が投下され、日本は【ポツダム宣言】を受け入れて降伏しました(8月15日に国民に伝えられた)。' }
    ],
    terms: [['不平等条約', '領事裁判権を認め、関税自主権がない条約'], ['廃藩置県', '1871年、藩をなくして府県を置き、中央集権のしくみをつくった改革'], ['地租改正', '1873年、地価の3%を土地所有者が現金で納める税にした改革'], ['三国干渉', 'ロシア・ドイツ・フランスが、遼東半島を清に返すよう求めたこと'], ['大正デモクラシー', '大正時代に広がった、民主主義を求める風潮'], ['普通選挙法', '1925年、満25歳以上のすべての男子に選挙権を与えた法']],
    miss: ['領事裁判権の撤廃(1894年・陸奥宗光)と関税自主権の回復(1911年・小村寿太郎)の順番や人物を取りちがえる。', 'ポーツマス条約で賠償金を得たと思ってしまう(得られなかったので暴動が起きた)。', '1925年の普通選挙法で女性にも選挙権が与えられたと思う(男子のみ。女性は戦後)。'],
    sum: ['開国で結んだ不平等条約を改めることが、明治の大きな目標だった。', '廃藩置県・学制・徴兵令・地租改正で近代国家のしくみを整えた。', '憲法と議会を整え、1894年と1911年に条約改正を達成。', '日清 → 三国干渉 → 日英同盟 → 日露 → 韓国併合 → 第一次大戦。', '世界恐慌 → 満州事変 → 国際連盟脱退 → 日中戦争 → 太平洋戦争。']
  };

  L.c_contemp = {
    goal: '戦後の民主化から独立回復、高度経済成長、冷戦の終結と現代の課題までの流れを、「国内」と「外交」に分けて説明できるようになる。',
    intro: '1945年の敗戦から、日本は国のしくみを大きく作りかえました。その後、焼け野原から世界有数の経済大国へと成長します。この時代は、国内の動き(民主化・経済)と、外交の動き(独立・国交回復)が、【冷戦】という世界の大きな対立と深く関わっています。2本の線に分けて整理すると、ぐっと分かりやすくなります。',
    secs: [
      { h: '占領と戦後の民主化', t: '敗戦後、日本はマッカーサーを最高司令官とする【GHQ(連合国軍総司令部)】の占領下で、民主化を進めました。\n【財閥解体】…経済を支配していた大企業の集団を解体した。\n【農地改革】…政府が地主の土地を買い上げ、小作人に安く売りわたした。その結果、多くの【自作農】が生まれた。\n選挙法が改正され、満20歳以上の【男女】に選挙権が与えられた(女性の参政権が初めて実現)。\n1946年11月3日に【日本国憲法】が公布され、1947年5月3日に施行された。国民主権・基本的人権の尊重・平和主義が原則。\nほかにも、教育基本法や労働組合法が定められました。',
        ex: [{ q: '農地改革で、農村はどう変わった?', steps: ['改革前:多くの農民は地主から土地を借りる小作人で、高い小作料に苦しんでいた。', '改革:政府が地主の土地を買い上げ、小作人に安く売りわたした。', '結果:自分の土地を耕す自作農が大幅にふえ、地主の力が弱まった。'], a: '地主の土地が小作人に安く売りわたされ、自作農が大幅にふえて、地主が農村を支配するしくみがくずれた。' }] },
      { h: '冷戦と独立の回復', t: '戦後の世界は、アメリカを中心とする資本主義の国々(西側)と、ソ連を中心とする社会主義の国々(東側)が対立する【冷戦】になりました。\n1950年に【朝鮮戦争】が始まると、アメリカは日本を西側の重要な国と考えるようになり、日本の独立を急ぎます。日本では、アメリカ軍が使う物資の注文で好景気(特需景気)になり、また【警察予備隊】がつくられました(のちの自衛隊)。\n1951年、【吉田茂】内閣は【サンフランシスコ平和条約】を結び、翌年に独立を回復しました。同時に【日米安全保障条約】を結び、独立後もアメリカ軍が日本にとどまることになりました。ただし、沖縄などはアメリカの統治下に残されました。\n1956年に【日ソ共同宣言】でソ連と国交を回復すると、それまで加盟に反対していたソ連が賛成にまわり、同じ年に日本は【国際連合に加盟】しました。',
        ex: [{ q: '次のできごとを古い順に並べよう。ア 国際連合への加盟 イ サンフランシスコ平和条約 ウ 沖縄の日本復帰 エ 日ソ共同宣言', steps: ['サンフランシスコ平和条約は1951年(独立回復は翌年)。', '日ソ共同宣言は1956年。ソ連との国交が回復した。', 'そのためソ連が賛成し、同じ1956年に国連加盟。', '沖縄の日本復帰は1972年。'], a: 'イ → エ → ア → ウ' }] },
      { h: '高度経済成長とその影', t: '1950年代半ばから1973年ごろまで、日本の経済は年平均で約10%という急成長を続けました(【高度経済成長】)。1964年には東京オリンピックが開かれ、東海道新幹線が開通しました。家庭には白黒テレビ・洗濯機・冷蔵庫が広まりました。\n一方で、工場の排水やけむりによる【公害】が深刻になり、水俣病・新潟水俣病・イタイイタイ病・四日市ぜんそくの【四大公害病】が起きました。政府は1967年に公害対策基本法を定め、1971年に環境庁をつくりました。\n1973年、中東での戦争をきっかけに石油の価格が急に上がる【石油危機(オイル・ショック)】が起き、高度経済成長は終わりました。\n外交では、1965年に日韓基本条約、1972年に【沖縄の日本復帰】と【日中共同声明】(中国との国交正常化)、1978年に日中平和友好条約が結ばれました。' },
      { h: '冷戦の終結と現代の日本', t: '1989年、東西対立の象徴だった【ベルリンの壁】がこわされ、米ソの首脳が冷戦の終結を宣言しました。1990年に東西ドイツが統一し、1991年にソ連が解体しました。\n日本では、1980年代後半に株や土地の値段が異常に上がる【バブル経済】が起き、1990年代の初めに崩壊して、長い不景気が続きました。\n1995年の阪神・淡路大震災、2011年の東日本大震災では大きな被害が出て、防災の大切さが見直されました。\n現在は、少子高齢化、地球環境問題、グローバル化への対応などが大きな課題です。' }
    ],
    terms: [['GHQ', '連合国軍総司令部。戦後の日本を占領し、民主化を指示した'], ['農地改革', '地主の土地を小作人に安く売りわたし、自作農をふやした改革'], ['冷戦', 'アメリカ中心の西側とソ連中心の東側の、直接戦火を交えない対立'], ['サンフランシスコ平和条約', '1951年、日本が連合国の多くと結んだ講和条約。翌年独立を回復'], ['高度経済成長', '1950年代半ばから1973年ごろまでの、日本経済の急成長'], ['石油危機', '1973年、石油価格の急上昇で世界経済が混乱したこと']],
    miss: ['サンフランシスコ平和条約で沖縄も返ったと思う(沖縄の復帰は1972年)。', '国連加盟を平和条約と同じ年と思う(加盟は日ソ共同宣言と同じ1956年)。', '日中共同声明(1972年)と日中平和友好条約(1978年)を混同する。'],
    sum: ['戦後改革:財閥解体・農地改革・男女普通選挙・日本国憲法。', '朝鮮戦争をきっかけに独立が急がれ、1951年に平和条約と安保条約。', '1956年の日ソ共同宣言で国連加盟が実現。', '高度経済成長は石油危機(1973年)で終わり、公害が課題に。', '1989年に冷戦が終結し、1991年にソ連が解体。']
  };

  L.c_m2 = {
    goal: '時代の順番と各時代の特徴をつかみ、できごとや文化を正しい時代に当てはめて並べかえられるようになる。',
    intro: '歴史の問題でいちばん多いのは、「どれが先?」という並べかえです。年号を全部覚えていなくても、【時代の順番】と【各時代の特徴】(だれが政治をしたか、都はどこか、どんな文化か)が分かっていれば、ほとんどの問題は解けます。この単元は、中学歴史全体の「地図」をつくるつもりで読みましょう。',
    secs: [
      { h: '時代の順番を口で言えるようにする', t: '旧石器 → 縄文 → 弥生 → 古墳 → 飛鳥 → 奈良 → 平安 → 鎌倉 → 室町(南北朝・戦国をふくむ)→ 安土桃山 → 江戸 → 明治 → 大正 → 昭和 → 平成 → 令和\n大きなまとまりでは、原始・古代(〜平安)、中世(鎌倉・室町)、近世(安土桃山・江戸)、近代(明治〜第二次世界大戦の終わり)、現代(戦後)に分けます。\n政治の中心で見ると:大王・天皇と豪族 → 天皇と貴族(律令)→ 藤原氏(摂関政治)→ 上皇(院政)→ 武士(幕府)→ 明治政府 → 政党・軍部 → 国民(日本国憲法)、と移っていきます。' },
      { h: '世紀の数え方', t: '1世紀は1年〜100年、2世紀は101年〜200年です。\n【下2けたが00でなければ、百の位より上の数に1を足す】。例:1543年 → 15+1=16世紀。\n【下2けたが00なら、そのまま】。例:1600年 → 16世紀(16世紀の最後の年)。\n紀元前(B.C.)は、さかのぼるほど数が大きくなります。',
        ex: [{ q: '1192年、1600年、1868年は、それぞれ何世紀?', steps: ['1192年:下2けたは92(00でない)→ 11+1=12世紀。', '1600年:下2けたが00 → そのまま16世紀。', '1868年:下2けたは68 → 18+1=19世紀。'], a: '12世紀、16世紀、19世紀' }] },
      { h: '文化で時代を見分ける', t: '文化の名前と時代をセットにすると、並べかえの強い手がかりになります。\n【飛鳥文化】(飛鳥・法隆寺)→【天平文化】(奈良・東大寺の大仏、正倉院)→【国風文化】(平安・かな文字、源氏物語)→【鎌倉文化】(武士の力強い文化、金剛力士像)→【北山文化】(室町・金閣、能)→【東山文化】(室町・銀閣、書院造)→【桃山文化】(安土桃山・天守閣のある城、茶の湯)→【元禄文化】(江戸前期・上方)→【化政文化】(江戸後期・江戸)\n人物も、その人が生きた時代とセットで覚えましょう。',
        ex: [{ q: '次の文化を古い順に並べよう。ア 元禄文化 イ 国風文化 ウ 北山文化 エ 天平文化', steps: ['天平文化は奈良時代(聖武天皇のころ)。', '国風文化は平安時代(遣唐使の停止後)。', '北山文化は室町時代(足利義満)。', '元禄文化は江戸時代前期。'], a: 'エ → イ → ウ → ア' }] },
      { h: '並べかえ問題の解き方', t: '①まず、それぞれのできごとが【どの時代】かを決める。時代がちがえば、それで順番が決まります。\n②同じ時代の中なら、【原因 → 結果】の関係で並べる。例:元寇 → 御家人の生活苦 → 徳政令。\n③それでも迷ったら、年号を思い出す。\nまた、「大政奉還をしたのはなぜ?」のような問いには、「背景(倒幕の動きが強まった)→ できごと → ねらい・結果」の順で答えると、記述問題にも対応できます。',
        ex: [{ q: '徳川慶喜が大政奉還を行ったのはなぜ?', steps: ['背景:薩摩藩・長州藩が薩長同盟を結び、武力で幕府を倒そうとする動きが強まっていた。', 'ねらい:武力で倒される前に自ら政権を朝廷に返し、新しい政治の中でも徳川家の影響力を残そうとした。'], a: '倒幕の動きが強まる中、武力で倒される前に政権を朝廷に返し、新しい政治の中でも徳川家の力を保とうとしたから。' }] }
    ],
    terms: [['時代区分', '歴史を、特徴によっていくつかの時代に分けること'], ['世紀', '100年ごとの区切り。1世紀は1〜100年'], ['紀元前', '西暦1年より前。B.C.と書く'], ['因果関係', 'あるできごと(原因)が別のできごと(結果)を引き起こす関係']],
    miss: ['1600年を17世紀と答える(下2けたが00ならそのまま16世紀)。', '北山文化(金閣)と東山文化(銀閣)を逆にする。', '年号の数字だけで並べようとして、時代の判断をとばしてしまう。'],
    sum: ['時代の順番は、口で言えるまで練習する。', '世紀は「下2けたが00でなければ百の位より上に+1」。', '文化名と時代、人物と時代はセットで覚える。', '並べかえは「時代 → 因果 → 年号」の順で考える。']
  };

  L.cx_jh3 = {
    goal: '難関校レベルの、年代の近いできごとの並べかえや「その結果どうなったか」を問う問題を、因果の流れから解けるようになる。',
    intro: '難関校の歴史は、年号を覚えているだけでは解けない問題が出ます。「Aの結果、何が起きたか」「BとC、どちらが先か(数年しかちがわない)」という問いです。これらは、できごとを【原因 → 結果】の矢印でつないで覚えていれば、年号を忘れても筋道で答えられます。この単元では、入試によく出る因果の鎖を練習します。',
    secs: [
      { h: '因果の鎖をつくる型', t: '因果は、次の3つの型でとらえると整理しやすくなります。\n【型1:しくみがくずれる】…土地やお金のしくみが変わり、支配がゆらぐ。例:墾田永年私財法 → 荘園の広がり → 公地公民の崩壊。元寇 → 恩賞不足 → 御恩と奉公の崩壊 → 鎌倉幕府の滅亡。\n【型2:外の動き → 国内の変化】…外交や戦争が国内の政治や経済を変える。例:開国 → 物価上昇 → 尊王攘夷 → 倒幕。世界恐慌 → 不景気 → 軍部の台頭。\n【型3:失敗 → 次の改革】…前の政治への反省から次の政治が生まれる。例:田沼の政治(わいろ・ききん)→ 寛政の改革。建武の新政(武士の不満)→ 室町幕府。\n年表を見たら、できごとどうしを矢印でつないでみる習慣をつけましょう。' },
      { h: '年代の近いできごとの並べかえ', t: '数年しかちがわないできごとは、「なぜ起きたか」から順番を決めます。\n例:日米修好通商条約(1858年)→ 安政の大獄(1858〜59年)→ 桜田門外の変(1860年)\n条約を朝廷の許可なく結んだ井伊直弼に反対する人々を、井伊がきびしく処罰した(安政の大獄)。その反発から、井伊が江戸城の桜田門外で暗殺された、という因果の順です。\n例:下関条約(1895年)→ 三国干渉(1895年)→ 日英同盟(1902年)→ ポーツマス条約(1905年)\n三国干渉で遼東半島を返させたロシアへの警戒が日英同盟を生み、日露戦争へつながりました。',
        ex: [{ q: '次のできごとを古い順に並べよう。ア 桜田門外の変 イ 薩長同盟 ウ 日米修好通商条約 エ 安政の大獄', steps: ['出発点は、井伊直弼が朝廷の許可なく結んだ日米修好通商条約(1858年)。', 'これに反対する人々を処罰したのが安政の大獄。', 'その反発で井伊直弼が暗殺されたのが桜田門外の変(1860年)。', '攘夷が難しいと知った薩摩・長州が倒幕に向けて結んだのが薩長同盟(1866年)。'], a: 'ウ → エ → ア → イ' }] },
      { h: '「その結果どうなったか」に答える', t: '結果を問われたら、【直後に起きた変化】と【長い目で見た影響】の2段階で考えます。\n例:応仁の乱(1467年)の結果 → 直後:京都が焼け、幕府の力が失われた。→ 長期:下剋上が広がり、戦国大名が各地を支配する戦国時代になった。\n例:承久の乱(1221年)の結果 → 直後:六波羅探題を置いて朝廷を監視。→ 長期:上皇方の土地に東国の御家人が地頭として入り、幕府の支配が西日本に広がった。',
        ex: [{ q: '世界恐慌(1929年)のあと、日本が国際的に孤立していった流れを説明しよう。', steps: ['世界恐慌で日本も深刻な不景気になり、人々の不満が高まった。', '軍(関東軍)は活路を中国東北部に求め、1931年に満州事変を起こし、満州国をつくった。', '国際連盟が満州国を認めなかったため、日本は1933年に国際連盟を脱退した。', 'こうして日本は国際的に孤立し、軍部の力が強まって日中戦争へ向かった。'], a: '世界恐慌による不景気 → 満州事変・満州国の建国 → 国際連盟が認めず連盟を脱退 → 国際的な孤立と軍部の台頭、という流れ。' }] },
      { h: '入試での答え方のコツ', t: '①記述では「〜だったので、〜した。その結果、〜になった」と、【原因・できごと・結果】を1文ずつ書く。\n②選択肢の問題では、「原因と結果が逆になっている」選択肢や、「時代がずれた人物」が入っている選択肢を消していく。\n③「なぜ」と聞かれたら、できごとの説明ではなく【理由】を答える(例:「大政奉還とは何か」ではなく「なぜ行ったか」)。' }
    ],
    terms: [['因果関係', '原因と結果のつながり'], ['安政の大獄', '井伊直弼が、条約や将軍のあとつぎに反対した大名・公家・武士を処罰したこと'], ['桜田門外の変', '1860年、井伊直弼が江戸城桜田門の外で暗殺された事件'], ['下剋上', '下の者が実力で上の者を倒すこと。応仁の乱の後に広がった']],
    miss: ['原因と結果を逆にした選択肢を選んでしまう(例:「御家人が困ったので元寇が起きた」)。', '「なぜ」と聞かれているのに、できごとの内容だけを書いてしまう。', '同じ年のできごとの順番を、因果を考えずにあてずっぽうで決める。'],
    sum: ['因果は「しくみの崩壊」「外の動き → 国内」「失敗 → 次の改革」の3つの型。', '年代の近いできごとは「なぜ起きたか」で順番を決める。', '結果は「直後の変化」と「長期の影響」の2段階で答える。', '記述は原因・できごと・結果を1文ずつ書く。']
  };

  // ===== 世界史探究 =====
  L.c_h2 = {
    goal: '古代から現代までの世界の大きな流れを、地域ごとの縦の流れと、同じ時代の横のつながりの両方で説明できるようになる。',
    intro: '世界史がむずかしく感じるのは、地域が多く、話がとびとびに見えるからです。でも、【「縦」=ある地域の流れ】と【「横」=同じ時代にほかの地域で起きていたこと】の2つを意識すると、1枚の大きな地図のようにつながってきます。たとえば、ヨーロッパの大航海時代は、アジアの明やオスマン帝国の豊かさを求めて始まりました。',
    secs: [
      { h: '古代:文明と大帝国', t: '大河の流域でオリエント・インダス・中国の文明が生まれ、その後、広い地域をまとめる大帝国ができました。\n【ギリシア】…アテネなどのポリス(都市国家)で、市民が政治に参加する民主政が行われた。\n【ローマ】…地中海を囲む大帝国をつくった。ローマ法やキリスト教が、のちのヨーロッパの土台になった。\n【中国】…秦の始皇帝が初めて中国を統一し、漢がそのしくみを受けついだ。シルクロードで西方と結ばれた。' },
      { h: '中世:イスラーム世界とヨーロッパ', t: '7世紀、アラビア半島で【ムハンマド】がイスラーム教を開き、イスラーム世界は西アジアから北アフリカ・イベリア半島へと広がりました。\n西ヨーロッパでは、国王・諸侯・騎士が土地を仲立ちに主従関係を結ぶ【封建社会】ができ、ローマ教皇を頂点とするカトリック教会が大きな力をもちました。\n11世紀末からの【十字軍】は、聖地エルサレムの回復を目的にくり返されましたが、最終的には失敗し、教皇の権威が低下するきっかけになりました。\n13世紀には【モンゴル帝国】がユーラシアの東西にまたがる大帝国をつくり、東西の交流がさかんになりました。' },
      { h: '近世:ヨーロッパの拡大とアジアの大帝国', t: '【ルネサンス】…14世紀にイタリアの都市から始まった、ギリシア・ローマの文化を手本に人間らしさを重んじる文化運動。\n【大航海時代】…アジアの香辛料などを直接手に入れるため、ポルトガル・スペインが新航路を開いた。1492年にコロンブスがアメリカ大陸近くの島に到達し、1498年にバスコ・ダ・ガマがインドに到達した。\n【宗教改革】…1517年、ドイツの【ルター】が教会の免罪符(贖宥状)の販売を批判し、プロテスタントが生まれた。\nヨーロッパでは、はっきりした国境と主権をもつ国家どうしが並び立つ【主権国家体制】ができていきました。\n同じころ、アジアでは中国の明・清、西アジアのオスマン帝国、インドのムガル帝国などの大帝国が栄えていました。' },
      { h: '近代:二つの革命と国民国家', t: '【市民革命】…王の権力をおさえ、市民の権利を広げる革命。イギリスの名誉革命(1688年)、アメリカ独立宣言(1776年)、【フランス革命】(1789年)。フランス革命の「自由・平等」の考えは、ナポレオンの遠征を通じてヨーロッパ各地に広がり、各地で国民としてまとまろうとする動き(ナショナリズム)を生みました。\n【産業革命】…18世紀後半のイギリスで、綿工業から始まった。機械と蒸気機関で大量生産ができるようになった。\nイギリスで最初に起きた理由:①植民地との貿易などで【資本】がたくわえられていた、②農業の変化で土地を失った人々が都市に流れこみ【労働力】があった、③【石炭・鉄鉱石】が豊富だった、④広い植民地を【市場】としてもっていた。\n19世紀後半になると、工業化した欧米の国々が、原料と市場を求めてアジア・アフリカを植民地にする【帝国主義】の時代になりました。',
        ex: [{ q: '産業革命が最初にイギリスで起きたのはなぜ?3つ以上の理由で説明しよう。', steps: ['資本:海外貿易などでお金(資本)がたくわえられていた。', '労働力:農業の変化で土地を失った農民が都市に集まり、工場で働く人がいた。', '資源:機械や燃料に必要な石炭・鉄鉱石が国内で豊富にとれた。', '市場:広い植民地があり、つくった製品を売る先があった。'], a: '資本のたくわえ、都市に集まった労働力、豊富な石炭・鉄鉱石、製品を売る植民地という市場がそろっていたから。' }] },
      { h: '現代:二つの世界大戦から冷戦、グローバル化へ', t: '帝国主義の国どうしの対立から【第一次世界大戦】(1914〜18年)が起こり、戦中の1917年には【ロシア革命】で世界初の社会主義国家が生まれました(のちのソ連)。戦後はヴェルサイユ条約で講和し、国際連盟がつくられました。\n1929年の【世界恐慌】で各国の経済が混乱し、ドイツなどではファシズムが台頭して、【第二次世界大戦】(1939〜45年)が起こりました。\n戦後は国際連合がつくられ、アメリカとソ連が対立する【冷戦】が続きました。1989年に冷戦が終わると、人・もの・お金が国境をこえて動く【グローバル化】が進みました。',
        ex: [{ q: '次のできごとを古い順に並べよう。ア フランス革命 イ 名誉革命 ウ ナポレオンが皇帝になる エ アメリカ独立宣言', steps: ['イギリスの名誉革命は1688年(17世紀)。', 'アメリカ独立宣言は1776年。', 'フランス革命は1789年。アメリカ独立戦争への支援による財政難も原因の一つ。', 'フランス革命後の混乱をおさめたナポレオンが1804年に皇帝に。'], a: 'イ → エ → ア → ウ' }] }
    ],
    terms: [['封建社会', '土地を仲立ちにした主従関係で成り立つ社会'], ['ルネサンス', 'イタリアから始まった、人間らしさを重んじる文化運動'], ['宗教改革', '1517年にルターが始めた、カトリック教会の改革運動'], ['主権国家体制', '主権をもつ国家どうしが対等に並び立つしくみ'], ['産業革命', '機械と動力による大量生産への変化。18世紀後半のイギリスから'], ['帝国主義', '工業国が原料と市場を求めて植民地を広げた動き']],
    miss: ['ルネサンスがイギリスやドイツから始まったと思う(イタリア)。', '産業革命の理由を「技術があったから」だけで答える(資本・労働力・資源・市場も)。', '名誉革命(1688年)とフランス革命(1789年)の世紀を取りちがえる。'],
    sum: ['地域ごとの「縦」と、同時代の「横」の両方で見る。', '中世:イスラーム世界の拡大、ヨーロッパの封建社会と十字軍。', '近世:ルネサンス・大航海時代・宗教改革、主権国家体制。', '近代:市民革命と産業革命(イギリスで最初)、帝国主義へ。', '現代:二つの世界大戦 → 冷戦 → グローバル化。']
  };

  L.hx_whist = {
    goal: '入試レベルの世界史で、できごとを「背景 → できごと → 結果」でつなぎ、地域をこえて広がる影響まで説明できるようになる。',
    intro: '入試の世界史では、「このできごとの結果、何が起きたか」「なぜこのできごとが起きたか」が問われます。世界史のできごとは、ある地域で起きたことが、海をこえて別の地域を動かしていることがよくあります。アメリカの独立がフランス革命につながり、イギリスの産業革命がインドや中国の運命を変えました。こうした「影響のドミノ」を追えるようになりましょう。',
    secs: [
      { h: '因果をとらえる3つの視点', t: 'できごとを見たら、次の3つを確認します。\n【背景(なぜ起きたか)】…長い間たまっていた問題。経済的な苦しさ、身分への不満、国どうしの対立など。\n【きっかけ】…直接の引き金になった事件。\n【結果と影響】…すぐに起きた変化と、ほかの地域や後の時代への影響。\n入試の選択肢では、「背景ときっかけの取りちがえ」や「結果を原因として書いた文」がよく誤りとして出されます。' },
      { h: '十字軍の結果', t: '十字軍(11世紀末〜13世紀)は失敗に終わりましたが、ヨーロッパ社会を大きく変えました。\n①くり返し失敗したことで、呼びかけた【ローマ教皇の権威が低下】した。\n②遠征に参加した【諸侯・騎士が没落】し、相対的に【国王の権力が強まった】。\n③軍や物資の輸送でイタリアの都市が栄え、東方との貿易(東方貿易)がさかんになった。\nこのイタリア都市の繁栄が、のちにイタリアで【ルネサンス】が始まる土台の一つになりました。',
        ex: [{ q: '十字軍の結果として誤っているものはどれ?ア 教皇の権威が低下した イ 国王の権力が弱まった ウ 東方貿易がさかんになった エ 諸侯・騎士が没落した', steps: ['教皇:失敗をくり返したので権威が低下した → 正しい。', '諸侯・騎士:遠征で力を失い没落した → 正しい。', 'そのぶん、国王の力は相対的に強まった → イの「弱まった」は逆。', '東方貿易:イタリア都市が栄えた → 正しい。'], a: 'イ' }] },
      { h: '大西洋をこえる革命のドミノ', t: '【背景】イギリスは七年戦争などで多額の借金をかかえ、北アメリカの植民地に新しい税をかけました(1765年の印紙法など)。\n【反発】植民地の人々は、本国の議会に代表を送っていないのに課税されることに反発しました(「代表なくして課税なし」)。\n【できごと】1775年に独立戦争が始まり、1776年に【独立宣言】を発表。フランスなどが植民地側を支援し、1783年のパリ条約でアメリカの独立が認められました。\n【影響】アメリカを支援したフランスは財政がさらに苦しくなり、ルイ16世は特権身分にも課税しようとして1789年に【三部会】を開きます。これをきっかけに【フランス革命】が始まりました。アメリカ独立宣言の考え方(人は生まれながらに自由で平等な権利をもつ)も、フランスの人権宣言に影響を与えました。',
        ex: [{ q: 'アメリカの独立が、フランス革命の原因の一つになったのはなぜ?', steps: ['フランスは、イギリスと対立していたこともあり、アメリカ独立戦争で植民地側を支援した。', 'その戦費で、もともと苦しかったフランスの財政がさらに悪化した。', '財政を立て直すため、国王は特権身分への課税を議論する三部会を開いた。', '三部会での対立から国民議会がつくられ、革命が始まった。また、独立宣言の思想も影響した。'], a: 'アメリカ独立戦争の支援でフランスの財政が悪化し、その立て直しのために開いた三部会が革命のきっかけになったから。独立宣言の自由・平等の思想も影響した。' }] },
      { h: '産業革命がアジアを変えた', t: 'イギリスで産業革命が進むと、機械でつくった安い綿織物がインドに大量に流れこみ、インドの手織りの綿織物業は大きな打撃を受けました。\nまた、イギリスは中国(清)から茶を大量に買っていたため、銀が中国へ流出していました。そこでイギリスは、インドでつくった【アヘン】を清に売り、イギリスの綿製品をインドへ、インドのアヘンを清へ、清の茶をイギリスへ、という【三角貿易】を行いました。\n清がアヘンを取りしまると、イギリスは【アヘン戦争】(1840〜42年)を起こし、勝って南京条約で香港島を手に入れ、上海などを開港させました。\nこのように、ヨーロッパの工業化は、アジアを原料の供給地・製品の市場へと組みこんでいきました。' },
      { h: '世界恐慌から第二次世界大戦へ', t: '1929年、ニューヨークの株式市場での株価の大暴落から【世界恐慌】が始まりました。各国の対応は分かれます。\n【アメリカ】…フランクリン=ローズヴェルト大統領が【ニューディール政策】で、公共事業などにより政府が経済に積極的に関わった。\n【イギリス・フランス】…広い植民地と本国を囲いこみ、外国の商品に高い関税をかける【ブロック経済】をとった。\n【ドイツ・イタリア・日本】…植民地が少なく行きづまり、軍事力で領土を広げようとする動きが強まった。ドイツではヒトラーのナチスが政権をにぎった。\n【ソ連】…計画経済(五か年計画)を進めていたため、恐慌の影響をあまり受けなかった。\nブロック経済で世界経済が分断されたことが、国どうしの対立を深め、第二次世界大戦の背景になりました。' }
    ],
    terms: [['三部会', 'フランスの身分制議会。1789年の招集が革命のきっかけになった'], ['三角貿易', 'イギリス・インド・清の間で、綿製品・アヘン・茶を回した貿易'], ['ニューディール政策', '世界恐慌に対しアメリカが行った、公共事業などによる経済政策'], ['ブロック経済', '本国と植民地で経済圏をつくり、外国商品をしめ出す政策'], ['東方貿易', '十字軍のころからさかんになった、イタリア都市と東方との貿易']],
    miss: ['十字軍の結果を「教皇の権威が高まった」と逆に覚える。', 'アヘン戦争を「清がイギリスにアヘンを売った」と取りちがえる(売ったのはイギリス)。', '世界恐慌でソ連も大きな打撃を受けたと思う(計画経済で影響が小さかった)。'],
    sum: ['できごとは「背景 → きっかけ → 結果・影響」で整理する。', '十字軍 → 教皇権の低下・王権の強化・東方貿易 → ルネサンスの土台。', 'アメリカ独立 → フランスの財政難 → 三部会 → フランス革命。', '産業革命 → インド綿業の打撃・三角貿易 → アヘン戦争。', '世界恐慌 → 各国の対応の差(ブロック経済など)→ 第二次世界大戦の背景。']
  };

  L.hd_wsoc = {
    goal: '難関大レベルの、年代の近いできごとの並べかえや、地域をまたぐ同時代の比較を、因果と年表の整理で正確に解けるようになる。',
    intro: '難関大の世界史では、「数年ちがい」「同じ年のうちの前後」まで問われます。これを年号の丸暗記だけで乗りきるのは大変です。コツは、①1つの国の中のできごとを因果の鎖でつなぐこと、②地域ごとの年表を1本に重ねて「同じころ、別の地域では何が起きていたか」を見ることです。',
    secs: [
      { h: '1つの国の流れを鎖にする:フランス革命とナポレオン', t: '1789年 三部会 → 国民議会 → バスティーユ牢獄襲撃 → 人権宣言\n1791年 憲法制定(立憲君主政)\n1792年 王政の廃止(第一共和政)\n1793年 ルイ16世の処刑 → ロベスピエールらの恐怖政治\n1794年 テルミドールのクーデタで恐怖政治が終わる\n1795年 総裁政府\n1799年 ナポレオンのブリュメール18日のクーデタ(統領政府)\n1804年 ナポレオン法典(民法典)の公布、ナポレオンが皇帝に即位\n1814〜15年 ウィーン会議\n「王の権力をおさえる → 王政をやめる → 急進化する → 反動で穏健化 → 混乱をおさめる強い指導者が登場」という流れで理解すると、順番が自然に決まります。',
        ex: [{ q: 'フランス革命の始まり(1789年)とナポレオンの皇帝即位(1804年)は何年ちがう?また、その間の政治体制を順に並べよう(ア 総裁政府 イ 第一共和政の成立 ウ 統領政府)。', steps: ['1804−1789=15年。', '1792年に王政が廃止され、第一共和政が成立。', '恐怖政治のあと、1795年に総裁政府。', '1799年のクーデタで統領政府ができ、ナポレオンが実権をにぎった。'], a: '15年。イ → ア → ウ' }] },
      { h: '対立の深まりを鎖にする:冷戦の始まり', t: '1947年 トルーマン・ドクトリン(共産主義の拡大をおさえる「封じこめ政策」)→ マーシャル・プラン(ヨーロッパの経済復興援助)\n1948年 ソ連が西ベルリンへの交通をふさぐ(ベルリン封鎖)\n1949年 西側の軍事同盟【NATO(北大西洋条約機構)】→ 東西ドイツの分立 → 中華人民共和国の成立\n1950年 朝鮮戦争\n1955年 東側の軍事同盟【ワルシャワ条約機構】\n1962年 キューバ危機\n「方針の表明 → 経済援助 → 対立の具体化(封鎖)→ 軍事同盟 → 実際の戦争」と、対立が段階的に深まる流れで並べます。ワルシャワ条約機構が1955年と遅いのは、西ドイツのNATO加盟への対抗としてつくられたからです。',
        ex: [{ q: '次のできごとを古い順に並べよう。ア 朝鮮戦争の開始 イ NATOの結成 ウ マーシャル・プランの発表 エ ワルシャワ条約機構の結成', steps: ['1947年、アメリカがヨーロッパ復興のためマーシャル・プランを発表。', '1948年のベルリン封鎖などで対立が深まり、1949年にNATO結成。', '1950年、朝鮮半島で実際の戦争(朝鮮戦争)が始まる。', '1955年、西ドイツのNATO加盟に対抗して、ワルシャワ条約機構。'], a: 'ウ → イ → ア → エ' }] },
      { h: '19世紀の中国:外からの圧力と内の動揺', t: '1840〜42年 アヘン戦争(南京条約)\n1851年 太平天国の乱(〜1864年)\n1856年 アロー戦争(〜1860年)\n1894年 日清戦争\n1900年 義和団事件(義和団戦争)\n1911年 辛亥革命 → 1912年 中華民国の成立、清の滅亡\n「外国との戦争に負けて負担が増える → 国内の反乱 → さらに外国の進出 → 外国を排除しようとする運動 → 王朝そのものを倒す革命」と、外と内の動きが交互に起きる流れです。' },
      { h: '横のつながりで並べる', t: '別々の地域のできごとを並べる問題では、各地域の年表を1本に重ねます。\n例:1789年(フランス革命)のころ、アメリカでは合衆国憲法にもとづいてワシントンが初代大統領に就任し、日本では松平定信が寛政の改革を進めていた。\n例:1840年代、中国ではアヘン戦争、日本では天保の改革、ヨーロッパでは1848年に各地で革命が起きた(フランスの二月革命など)。\n例:1917年、ロシアでは二月革命と十月革命、アメリカは第一次世界大戦に参戦。\n日本史で知っている年号を「目印」にして、同じころの世界を思いうかべる練習が効果的です。' }
    ],
    terms: [['恐怖政治', 'ロベスピエールらが反対派を次々に処刑した政治'], ['総裁政府', '1795年からの、5人の総裁による不安定な政府'], ['封じこめ政策', 'アメリカが共産主義の拡大をおさえるためにとった政策'], ['NATO', '1949年に結成された、アメリカ中心の西側の軍事同盟'], ['辛亥革命', '1911年に始まり、清をほろぼして中華民国をつくった革命']],
    miss: ['王政廃止(1792年)とルイ16世の処刑(1793年)の順を逆にする。', 'ワルシャワ条約機構をNATOと同じ1949年と思う(1955年)。', '太平天国の乱とアロー戦争を、アヘン戦争より前に置く。'],
    sum: ['1つの国の流れは、因果の鎖で順番を決める。', 'フランス:革命(1789)→ 共和政(1792)→ 総裁政府(1795)→ 統領政府(1799)→ 皇帝(1804)。', '冷戦:マーシャル・プラン → NATO → 朝鮮戦争 → ワルシャワ条約機構。', '別地域は年表を重ね、日本史の年号を目印にする。']
  };

  // ===== 日本史探究 =====
  L.c_h1 = {
    goal: '日本史の流れを、政治の担い手・土地と税・外交という「テーマ」ごとに通して説明でき、政策を「だれが・なぜ・結果どうなったか」で整理できるようになる。',
    intro: '日本史探究は、中学の歴史をくわしくしたものです。ただ覚える量が多いので、時代ごとに分けて覚えるだけでは、つながりが見えなくなります。そこで、【テーマ史】という見方を使います。たとえば「土地と税のしくみ」を古代から近代まで1本の線でたどると、それぞれの政策がなぜ必要だったのかがよく分かります。',
    secs: [
      { h: '政治の担い手の移り変わり', t: '大王と豪族(古墳)→ 天皇中心の律令国家(飛鳥・奈良)→ 藤原氏の摂関政治(平安中期)→ 上皇の院政(平安後期)→ 平氏政権 → 鎌倉幕府(将軍 → 北条氏の執権)→ 室町幕府(将軍と守護大名)→ 戦国大名 → 織豊政権 → 江戸幕府(幕藩体制)→ 明治政府(藩閥)→ 政党内閣(大正〜昭和初期)→ 軍部の台頭 → 戦後の民主政治(国民主権)\n「前の担い手がなぜ力を失い、次の担い手がなぜ力をにぎれたのか」を説明できるようにしましょう。たとえば院政は、上皇が天皇の父という立場で、摂関家(藤原氏)の外戚としての力をおさえて政治を行ったものです。' },
      { h: 'テーマ史:土地と税のしくみ', t: '【班田収授法】(律令国家)…戸籍にもとづき口分田を与え、租・調・庸を課す。\n【三世一身法】(723年)…開墾した土地を3代まで私有できる。期限が来ると返すので、効果はうすかった。\n【墾田永年私財法】(743年)…開墾地の永久私有を認めた。ねらいは開墾の促進。結果、貴族・寺社の私有地(のちの荘園)が広がった。\n【寄進地系荘園】(平安中期以降)…地方の有力者が、税をのがれるために土地を中央の貴族や寺社に寄進した。不輸(税を納めない)・不入(役人を入れない)の権を得る荘園が広がり、国の財政がゆらいだ。\n【延久の荘園整理令】(1069年、後三条天皇)…基準に合わない荘園を整理した。\n【太閤検地】(豊臣秀吉)…1つの土地の耕作者を1人に決め(一地一作人)、石高で表した。荘園のしくみが最終的に消えた。\n【地租改正】(1873年)…地価の3%を土地所有者が現金で納める。税収の安定がねらい。\n【農地改革】(戦後)…地主の土地を小作人に売りわたし、自作農をふやした。',
        ex: [{ q: '次の政策を古い順に並べよう。ア 太閤検地 イ 三世一身法 ウ 地租改正 エ 墾田永年私財法', steps: ['三世一身法(723年)は、開墾地を3代に限って私有させた。', 'それでも開墾が進まず、墾田永年私財法(743年)で永久私有を認めた。', '太閤検地(16世紀末)で荘園のしくみが消え、石高制になった。', '地租改正(1873年)で近代的な税制になった。'], a: 'イ → エ → ア → ウ' }] },
      { h: 'テーマ史:外交の流れ', t: '遣隋使・遣唐使(大陸の制度・文化を学ぶ)→ 遣唐使の停止(894年)→ 日宋貿易(平清盛)→ 元寇(1274・1281年)→ 日明貿易(勘合貿易、足利義満)→ 南蛮貿易(ポルトガル・スペイン)→ 朱印船貿易 → 鎖国(4つの窓口)→ 開国(1854年・1858年)→ 条約改正(1894年・1911年)→ 日清・日露戦争 → 国際連盟脱退(1933年)→ 第二次世界大戦 → サンフランシスコ平和条約(1951年)・国連加盟(1956年)\n外交は、その時代の国内の政治と結びついています。たとえば鎖国は、キリスト教の禁止と、幕府が貿易の利益と情報を独占するためのものでした。' },
      { h: '政策は「だれが・なぜ・結果どうなったか」', t: '入試では、政策の名前よりも、そのねらいと結果が問われます。次の3点を必ずセットにしましょう。\n①【だれが】…人物・政権。時代を特定する手がかりになる。\n②【なぜ】…背景にある問題(財政難、ききん、外国の圧力など)。\n③【結果】…成功したか、どんな反発や新しい問題が生まれたか。\n例:天保の改革(水野忠邦)…なぜ:ききんや一揆、外国船の接近で幕府の危機が深まった。何を:株仲間の解散、倹約令など。結果:反発が強く、2年余りで失敗し、幕府の権威が低下した。',
        ex: [{ q: '地租改正(1873年)の「なぜ」と「結果」を説明しよう。', steps: ['なぜ:江戸時代の年貢は米で、豊作・不作で収入が変わり、明治政府の財政が安定しなかった。', '何を:地券を発行して土地所有者を決め、地価の3%を現金で納めさせた。', '結果:国の税収は安定した。しかし農民の負担は軽くならず、各地で地租改正反対一揆が起き、1877年に税率は2.5%に引き下げられた。'], a: '税収を安定させるため、地価の3%を土地所有者に現金で納めさせた。税収は安定したが、負担の重さに反対一揆が起き、税率が2.5%に引き下げられた。' }] }
    ],
    terms: [['テーマ史', '土地制度・外交など、1つのテーマで時代を通して見る見方'], ['寄進地系荘園', '有力者が土地を貴族や寺社に寄進してできた荘園'], ['不輸・不入の権', '税を納めない権利と、国の役人を立ち入らせない権利'], ['一地一作人', '太閤検地で、1つの土地の耕作者を1人に決めたこと'], ['幕藩体制', '将軍(幕府)と大名(藩)が土地と人々を支配するしくみ']],
    miss: ['三世一身法と墾田永年私財法の順番・内容を逆にする。', '太閤検地で荘園が「広がった」と思う(荘園のしくみは消えた)。', '政策の名前だけ覚えて、ねらいと結果を答えられない。'],
    sum: ['政治の担い手の移り変わりを1本の線で言えるようにする。', '土地と税は 班田収授 → 墾田永年私財法 → 荘園 → 太閤検地 → 地租改正 → 農地改革。', '外交は国内の政治と結びつけて理解する。', '政策は「だれが・なぜ・結果どうなったか」の3点セット。']
  };

  L.hx_jhist = {
    goal: '入試レベルの日本史で、できごとを「背景 → できごと → 結果」でつなぎ、結果から原因をたどる問題にも答えられるようになる。',
    intro: '入試の日本史では、「〜の結果として正しいものは?」「〜が起きた背景は?」という問題がたくさん出ます。できごとを1つずつ覚えるのではなく、【前のできごとが原因になって次のできごとが起き、それがまた次の原因になる】という鎖で覚えると、知らない形の問題でも筋道で考えられます。',
    secs: [
      { h: '因果をたどる練習の型', t: '①【前に向かってたどる】…「このできごとはなぜ起きたか」→ 背景(長い間の問題)ときっかけ(直接の事件)に分ける。\n②【後ろに向かってたどる】…「このできごとの結果、何が起きたか」→ 直後の変化と、その後の影響。\n③【結果から原因をさがす】…入試では、結果が書かれていて「その原因となったできごと」を選ばせる問題もある。年表を逆向きに読む練習が効く。\nたとえば「田沼意次の失脚」なら、背景=わいろ政治への批判、きっかけ=天明のききんと打ちこわしの広がり、結果=松平定信の寛政の改革、とつながります。' },
      { h: '開国が国内に与えた影響', t: '1858年の日米修好通商条約で、翌年から貿易が始まりました。\n【生糸・茶が大量に輸出】され、国内で品不足になって物価が上がりました。\n【金の流出】…日本では金と銀の交換比率が約1:5、外国では約1:15でした。外国人は銀を日本に持ちこんで金に換え、大量の金が海外に流出しました。幕府は金の量を減らした小判をつくって対応しましたが、これが物価の上昇をさらに強めました。\nこうした生活の苦しさから、外国を追いはらえという【攘夷運動】が強まり、幕府への批判にもつながっていきました。',
        ex: [{ q: '開国後に攘夷運動が強まったのはなぜ?経済の面から説明しよう。', steps: ['貿易が始まり、生糸などが大量に輸出されて国内で品不足になった。', '金銀の交換比率のちがいから金が海外に流出し、幕府が質を下げた小判を出したことで物価がさらに上がった。', '人々の生活が苦しくなり、その原因である外国と、条約を結んだ幕府への不満が高まった。'], a: '輸出による品不足や金の流出、質を下げた小判の発行で物価が急に上がり、生活が苦しくなった人々の不満が外国と幕府に向かったから。' }] },
      { h: '明治の改革への反発と政府の対応', t: '【地租改正】(1873年)→ 負担が軽くならないことへの反発から各地で【地租改正反対一揆】→ 政府は1877年に地租を地価の3%から【2.5%】に引き下げた。\n【徴兵令・廃刀令・秩禄処分】で特権を失った士族の不満 → 各地で士族の反乱 → 最大の反乱が1877年の【西南戦争】(西郷隆盛)→ 政府軍(徴兵による軍隊)が勝ち、武力による反乱は終わる → 以後、政府への批判は言論による【自由民権運動】が中心になる。\n「武力での反抗が無理だと分かった → 言論で戦う方向へ」という流れが、国会開設や憲法制定につながりました。' },
      { h: '戦争・恐慌と国内政治', t: '【日露戦争】(1904〜05年)…国民は増税にたえて戦ったが、ポーツマス条約で賠償金が得られず → 【日比谷焼き打ち事件】。\n【第一次世界大戦】(1914〜18年)…輸出がのびて好景気(大戦景気)→ 物価が上がる → シベリア出兵を見こした米の買い占めで米価が急上昇 → 1918年の【米騒動】→ 寺内内閣が退陣し、【原敬】の本格的な政党内閣が成立。\n【世界恐慌】(1929年)…金解禁(1930年)と重なり、日本は【昭和恐慌】におちいる。生糸の輸出が激減し、農村が特に苦しんだ → 政党や財閥への不満が高まる → 軍部が満州に活路を求め、1931年に満州事変。',
        ex: [{ q: '米騒動(1918年)の背景と、その結果を説明しよう。', steps: ['背景:第一次世界大戦の好景気で物価が上がっていた。', 'きっかけ:シベリア出兵を見こした米の買い占めで、米の値段が急に上がった。', 'できごと:富山県から始まり、米の安売りを求める騒動が全国に広がった。', '結果:責任をとって内閣が退陣し、原敬による本格的な政党内閣が成立した。'], a: '大戦景気による物価上昇と、シベリア出兵を見こした米の買い占めで米価が急上昇したことから米騒動が全国に広がり、その結果、原敬の本格的な政党内閣が成立した。' }] }
    ],
    terms: [['攘夷', '外国を追いはらおうとする考え'], ['金の流出', '金銀の交換比率のちがいから、開国後に大量の金が海外へ出たこと'], ['西南戦争', '1877年、西郷隆盛を中心とする士族の最大の反乱'], ['米騒動', '1918年、米価の急上昇に対して全国に広がった騒動'], ['昭和恐慌', '世界恐慌と金解禁が重なって起きた、昭和初期の深刻な不景気']],
    miss: ['米騒動の結果を「政党内閣が終わった」と逆に覚える(本格的な政党内閣が始まった)。', '開国後の物価上昇の原因を「輸入が増えたから」とだけ答える(輸出による品不足と金の流出が重要)。', '西南戦争の後も士族の武力反乱が続いたと思う(以後は言論による自由民権運動が中心に)。'],
    sum: ['因果は「前へ(なぜ)」「後ろへ(結果)」「結果から原因へ」の3方向で練習する。', '開国 → 品不足・金の流出・物価上昇 → 攘夷運動。', '地租改正反対一揆 → 2.5%に引き下げ。西南戦争 → 言論の自由民権運動へ。', '大戦景気 → 米騒動 → 原敬内閣。世界恐慌 → 昭和恐慌 → 満州事変。']
  };

  L.hd_jsoc = {
    goal: '難関大レベルの、数年・数か月ちがいのできごとの並べかえを、因果と政治の流れから正確に判断できるようになる。',
    intro: '難関大の日本史では、「大政奉還と王政復古の大号令、どちらが先?」のように、とても近いできごとの順番が問われます。これは、年号だけでなく「何が起きたから、次に何が起きたのか」を理解しているかを試す問題です。この単元では、入試に出やすい「近いできごとのかたまり」を、因果で並べる練習をします。',
    secs: [
      { h: '幕末から明治初めのかたまり', t: '1866年 薩長同盟\n1867年10月 【大政奉還】(徳川慶喜が政権を朝廷に返す)\n1867年12月 【王政復古の大号令】(幕府を廃止し、天皇中心の新政府をつくる宣言)\n1868年1月 鳥羽・伏見の戦い(戊辰戦争の始まり)\n1868年3月 五箇条の御誓文\n1868年4月 江戸城の無血開城\n1869年 箱館の五稜郭の戦いで戊辰戦争が終わる/版籍奉還\n1871年 廃藩置県\n因果:慶喜は大政奉還で新政府の中に徳川家の力を残そうとした → 倒幕派はそれを防ぐため王政復古の大号令で慶喜を新政府から外し、領地の返上も求めた → 旧幕府側が反発して戊辰戦争。',
        ex: [{ q: '次のできごとを古い順に並べよう。ア 鳥羽・伏見の戦い イ 王政復古の大号令 ウ 大政奉還 エ 五箇条の御誓文', steps: ['まず慶喜が政権を朝廷に返す(大政奉還、1867年10月)。', 'それに対し、倒幕派が天皇中心の新政府を宣言(王政復古の大号令、1867年12月)。', '新政府の処置に旧幕府側が反発し、戦いになる(鳥羽・伏見の戦い、1868年1月)。', '戦いが続く中で、新政府が政治の方針を示す(五箇条の御誓文、1868年3月)。'], a: 'ウ → イ → ア → エ' }] },
      { h: '満州事変から国際連盟脱退までのかたまり', t: '1931年9月 【満州事変】(柳条湖事件がきっかけ)\n1932年3月 【満州国】の建国宣言\n1932年5月 【五・一五事件】(犬養毅首相が暗殺され、政党内閣が終わる)\n1932年9月 日満議定書(日本が満州国を承認)\n1932年10月 リットン調査団の報告書が公表される\n1933年3月 【国際連盟脱退】を通告\n因果:満州国を承認することに慎重だった犬養首相が暗殺される → 次の内閣が満州国を承認(日満議定書)→ 国際連盟はリットン報告書にもとづき満州国を認めない → 日本は連盟を脱退。',
        ex: [{ q: '次のできごとを古い順に並べよう。ア 国際連盟脱退の通告 イ 五・一五事件 ウ 満州事変 エ 日満議定書', steps: ['出発点は満州事変(1931年)。', '満州国が建国され、その承認に慎重だった犬養首相が五・一五事件(1932年5月)で暗殺される。', '次の内閣が日満議定書(1932年9月)で満州国を承認。', '国際連盟が満州国を認めず、日本は脱退を通告(1933年)。'], a: 'ウ → イ → エ → ア' }] },
      { h: '大正期のかたまり', t: '1912〜13年 第一次護憲運動(桂太郎内閣が退陣)\n1914年 第一次世界大戦に参戦\n1915年 中国に二十一か条の要求\n1918年 シベリア出兵を見こした米の買い占め → 米騒動 → 原敬内閣\n1923年 関東大震災\n1924年 第二次護憲運動 → 加藤高明内閣(護憲三派)\n1925年 普通選挙法と治安維持法\n普通選挙法と治安維持法は同じ1925年です。選挙権を広げると社会主義の運動が強まることを政府がおそれ、取りしまりの法律をセットでつくった、という因果で覚えます。' },
      { h: '近いできごとを並べるときの手順', t: '①【起点】をさがす…ほかのできごとの原因になっている最初のできごと(多くは条約・戦争・事件)。\n②【反応】を並べる…起点に対して、だれがどう反応したか(賛成・反対・処罰・反乱)。\n③【決着】を最後に置く…条約の締結、内閣の交代、制度の成立など。\nこの「起点 → 反応 → 決着」の型は、どの時代のかたまりにも使えます。どうしても判断できないときだけ、月まで覚えている知識にたよりましょう。' }
    ],
    terms: [['王政復古の大号令', '1867年12月、幕府を廃止し天皇中心の新政府をつくると宣言したもの'], ['戊辰戦争', '1868〜69年、新政府軍と旧幕府側との戦い'], ['日満議定書', '1932年、日本が満州国を承認した取り決め'], ['リットン調査団', '国際連盟が満州事変の調査のために送った調査団'], ['護憲運動', '藩閥や官僚の政治に反対し、憲法にもとづく政党政治を求めた運動']],
    miss: ['王政復古の大号令を大政奉還より前に置く(大政奉還が先)。', '五箇条の御誓文を戊辰戦争の前に置く(鳥羽・伏見の戦いのあと)。', '国際連盟脱退を満州国建国と同じ1932年にしてしまう(1933年)。'],
    sum: ['近いできごとは「起点 → 反応 → 決着」で並べる。', '大政奉還(1867.10)→ 王政復古(1867.12)→ 鳥羽・伏見(1868.1)→ 五箇条の御誓文(1868.3)。', '満州事変 → 満州国 → 五・一五事件 → 日満議定書 → 連盟脱退(1933)。', '1925年の普通選挙法と治安維持法はセットで理解する。']
  };

  // ===== 中学公民 =====
  L.c_gendai = {
    goal: '現代社会の特色(少子高齢化・グローバル化・情報化)を説明でき、「効率」と「公正」の考え方で、対立を合意にみちびく方法を考えられるようになる。',
    intro: '公民は「今の社会のしくみ」を学ぶ科目です。その入り口として、まず今の日本がどんな社会なのかを見ます。そして、人が集まって暮らせば必ず意見の対立が起きます。そのときに、みんなが納得できる決め方を考える道具が【効率】と【公正】です。これは学級会の話し合いから国の政治まで、同じように使えます。',
    secs: [
      { h: '少子高齢化', t: '【少子化】…生まれる子どもの数が減ること。1人の女性が一生のうちに産む子どもの数の平均を【合計特殊出生率】といい、およそ2.1を下回り続けると人口は減っていきます。日本はこれを大きく下回っています。\n【高齢化】…総人口にしめる65歳以上の人の割合(高齢化率)が高まること。日本は約3割に達しています。\nこの2つが同時に進むと、働く世代が減り、年金や医療などの社会保障を支える人1人あたりの負担が重くなります。保育サービスの充実や、高齢者が働き続けられるしくみづくりなどが課題です。',
        ex: [{ q: 'ある町の人口は2000人で、そのうち65歳以上が500人。高齢化率は何%?', steps: ['高齢化率=65歳以上の人口÷総人口×100。', '500÷2000=0.25。', '0.25×100=25%。'], a: '25%' }] },
      { h: 'グローバル化と情報化', t: '【グローバル化】…人・もの・お金・情報が国境をこえて行き来し、世界の一体化が進むこと。得意なものを生産して交換し合う【国際分業】が進む一方、国内の工場が海外に移って国内の産業がおとろえる心配もあります。外国から来た人々とともに暮らす【多文化共生】も大切になっています。\n【情報化】…情報通信技術(ICT)が発達し、情報が社会の中で大きな役割をもつようになること。インターネットやAI(人工知能)で生活は便利になりましたが、個人情報の流出や、うその情報の拡散などの問題もあります。情報を正しく選び、活用する力を【情報リテラシー】といいます。' },
      { h: '対立から合意へ:効率と公正', t: '社会では、考え方や利害のちがいから【対立】が生まれます。話し合いで【合意】をめざすとき、次の2つの考え方で解決策を確かめます。\n【効率】…お金・時間・労力・ものなどを、むだなく使えているか。\n【公正】…一部の人だけが不利になっていないか。公正には2種類あります。\n・【手続きの公正さ】…関係する全員が話し合いに参加し、意見を言える機会があったか。\n・【機会や結果の公正さ】…立場によって機会や結果が不当に差別されていないか。\n決め方には、全員が賛成するまで話し合う【全会一致】(納得は得やすいが時間がかかる)と、【多数決】(早く決まるが少数意見が反映されにくい)があります。多数決をとる前に、【少数意見の尊重】を十分に行うことが大切です。',
        ex: [{ q: '体育館を使う時間を、部員数に関係なく、すべての部に同じ時間ずつ割り当てた。その結果、人数の少ない部では使われない時間ができた。この決め方は、効率と公正のどちらの面で問題がある?', steps: ['使われない時間ができている=体育館という資源がむだになっている。', 'むだがないかを見るのは「効率」の考え方。', '全部の部に同じ時間なので、機会の点では一見公正だが、むだが生じている。'], a: '効率の面で問題がある(体育館の時間がむだになっている)。' }] },
      { h: '持続可能な社会をめざして', t: '今の世代の豊かさのために、将来の世代の環境や資源を使いつくしてはいけません。将来の世代の必要を満たす力をそこなわずに、今の世代の必要を満たす社会を【持続可能な社会】といいます。\n2015年に国連で採択された【SDGs(持続可能な開発目標)】は、貧困・飢餓・教育・気候変動など17の目標を、2030年までに達成することをめざしています。\n身近な生活の中で、ごみを減らす、エネルギーを節約するなどの行動も、持続可能な社会につながります。' }
    ],
    terms: [['合計特殊出生率', '1人の女性が一生のうちに産む子どもの数の平均'], ['高齢化率', '総人口にしめる65歳以上の人口の割合'], ['グローバル化', '人・もの・お金・情報が国境をこえて行き来し、世界の一体化が進むこと'], ['情報リテラシー', '情報を正しく選び、活用する力'], ['効率と公正', 'むだがないか(効率)と、一部の人が不利になっていないか(公正)'], ['SDGs', '2015年に国連で採択された、2030年までの17の持続可能な開発目標']],
    miss: ['効率と公正を逆に覚える(むだがないか=効率)。', '多数決なら必ず公正だと思う(少数意見の尊重や手続きの公正さが必要)。', '少子化と高齢化を同じ意味だと思う(子どもが減ること/高齢者の割合が高まること)。'],
    sum: ['現代社会の特色は少子高齢化・グローバル化・情報化。', '少子高齢化で、社会保障を支える世代の負担が重くなる。', '対立を合意にするときは「効率」と「公正」で確かめる。', '多数決の前に少数意見を尊重する。', '持続可能な社会をめざす国際目標がSDGs。']
  };

  L.c_m3 = {
    goal: '日本国憲法の原則と基本的人権、国会・内閣・裁判所のしくみと三権分立、選挙と地方自治を、理由とともに説明できるようになる。',
    intro: '国の政治は、国民が選んだ代表者が行います。でも、もし1人や1つの機関に権力が集中したら、国民の自由が守られなくなるかもしれません。そこで、権力を3つに分けてたがいに見張らせる【三権分立】や、国の最高のきまりである【憲法】で権力をしばるしくみがあります。「なぜそういうしくみなのか」を考えながら読むと、用語がすっと入ってきます。',
    secs: [
      { h: '日本国憲法の三大原則と人権', t: '日本国憲法は1946年11月3日に公布、1947年5月3日に施行されました。三大原則は【国民主権・基本的人権の尊重・平和主義】です。\n天皇は日本国と日本国民統合の【象徴】で、政治の権限をもたず、内閣の助言と承認によって国事行為を行います。\n基本的人権:【平等権】、【自由権】(精神の自由・身体の自由・経済活動の自由)、【社会権】(「健康で文化的な最低限度の生活」を営む権利=生存権、教育を受ける権利、勤労の権利、労働者の権利)、【参政権】、【請求権】(裁判を受ける権利など)。\n社会の変化にともなって、環境権・知る権利・プライバシーの権利・自己決定権などの【新しい人権】も主張されています。\n人権は、他の人の人権とぶつかるときなどに、【公共の福祉】によって制限されることがあります。\n憲法改正は、各議院の総議員の3分の2以上の賛成で国会が発議し、国民投票で過半数の賛成が必要です。' },
      { h: '国会・内閣・裁判所', t: '【国会】(立法)…国権の最高機関で、唯一の立法機関。衆議院と参議院の二院制。\n・衆議院:任期4年、解散あり、被選挙権25歳以上。\n・参議院:任期6年(3年ごとに半数を改選)、解散なし、被選挙権30歳以上。\n任期が短く解散もある衆議院のほうが国民の意見を反映しやすいと考えられ、予算の先議や内閣不信任決議など【衆議院の優越】が認められています。\n【内閣】(行政)…内閣総理大臣と国務大臣で構成。総理大臣は国会議員の中から国会が指名します。内閣が国会の信任にもとづいて成り立ち、国会に対して責任を負うしくみを【議院内閣制】といいます。衆議院で内閣不信任決議が可決されると、内閣は10日以内に衆議院を解散しないかぎり、総辞職しなければなりません。\n【裁判所】(司法)…最高裁判所と下級裁判所。1つの事件で3回まで裁判を受けられる【三審制】をとります。すべての裁判所が、法律などが憲法に違反していないかを判断する【違憲審査権】をもち、最終的に判断する最高裁判所は「憲法の番人」とよばれます。',
        ex: [{ q: '衆議院で内閣不信任の決議が可決された。内閣がとれる対応を2つ答えよう。', steps: ['議院内閣制では、内閣は国会(衆議院)の信任の上に成り立っている。', '信任を失ったので、内閣は総辞職するか、', '10日以内に衆議院を解散して、選挙で国民の判断を問う。'], a: '10日以内に衆議院を解散する、または総辞職する。' }] },
      { h: '三権分立:なぜ権力を分けるのか', t: '権力が1つに集まると、それが乱用されて国民の自由がおびやかされるおそれがあります。そこで、立法・行政・司法の3つの権力を別々の機関にもたせ、たがいに【抑制と均衡】をはかるのが【三権分立】です。フランスのモンテスキューが「法の精神」で説きました。\n国会 → 内閣:内閣総理大臣の指名、内閣不信任の決議。\n内閣 → 国会:衆議院の解散。\n国会 → 裁判所:裁判官をやめさせるかを決める弾劾裁判。\n内閣 → 裁判所:最高裁判所長官の指名、その他の裁判官の任命。\n裁判所 → 国会・内閣:法律や行政処分が憲法に違反していないかの審査。\nさらに国民は、選挙(国会)、世論(内閣)、最高裁判所裁判官の国民審査(裁判所)を通じて、三権に関わります。' },
      { h: '選挙と地方自治', t: '選挙の4原則:一定の年齢以上のすべての国民が投票できる【普通選挙】、1人1票の【平等選挙】、だれに投票したか知られない【秘密選挙】、直接候補者に投票する【直接選挙】。選挙権は満18歳以上です。\n衆議院議員の選挙は、小選挙区制と比例代表制を組み合わせた【小選挙区比例代表並立制】です。\n地方自治は、住民が身近な政治に参加して民主主義を学べることから「【民主主義の学校】」とよばれます。住民は首長(知事・市町村長)と地方議員をそれぞれ直接選挙で選びます。\n住民には【直接請求権】があります(原則):\n・条例の制定・改廃、監査の請求…有権者の【50分の1以上】の署名(条例は首長へ、監査は監査委員へ)。\n・議会の解散、首長・議員の解職(リコール)…有権者の【3分の1以上】の署名を選挙管理委員会へ。',
        ex: [{ q: '有権者が9万人の市で、条例の制定を請求したい。何人以上の署名が必要で、どこに請求する?', steps: ['条例の制定・改廃の請求は、有権者の50分の1以上の署名が必要。', '90000÷50=1800。', '請求先は首長(市長)。'], a: '1800人以上の署名を集め、市長に請求する。' }] }
    ],
    terms: [['国民主権', '国の政治のあり方を最終的に決める力が国民にあること'], ['公共の福祉', '社会全体の利益。人権どうしの対立を調整する考え方'], ['議院内閣制', '内閣が国会の信任にもとづいて成り立ち、国会に対して責任を負うしくみ'], ['違憲審査権', '法律などが憲法に違反していないかを判断する裁判所の権限'], ['三審制', '1つの事件で3回まで裁判を受けられるしくみ'], ['直接請求権', '住民が署名を集めて、条例の制定や首長の解職などを求める権利']],
    miss: ['衆議院と参議院の任期・被選挙権(4年・25歳/6年・30歳)を逆にする。', '内閣総理大臣を国民が直接選ぶと思う(国会が指名する)。', '条例の請求(50分の1・首長へ)と解職の請求(3分の1・選挙管理委員会へ)を混同する。'],
    sum: ['三大原則は国民主権・基本的人権の尊重・平和主義。', '国会=立法、内閣=行政、裁判所=司法。たがいに抑制し合うのが三権分立。', '議院内閣制:不信任決議 → 10日以内に解散か総辞職。', '選挙は普通・平等・秘密・直接の4原則、満18歳以上。', '地方自治は「民主主義の学校」。直接請求は50分の1と3分の1。']
  };

  var SUPPLY = '<svg viewBox="0 0 220 150" class="lz-fig" role="img" aria-label="需要曲線と供給曲線の交点で均衡価格が決まる"><line x1="30" y1="130" x2="210" y2="130" class="ax"/><line x1="30" y1="10" x2="30" y2="130" class="ax"/><line x1="50" y1="25" x2="190" y2="120" class="cv"/><line x1="50" y1="120" x2="190" y2="25" class="cv2"/><line x1="30" y1="72.5" x2="120" y2="72.5" class="dash"/><line x1="120" y1="72.5" x2="120" y2="130" class="dash"/><circle cx="120" cy="72.5" r="4" class="pt"/><text x="34" y="20">価格</text><text x="184" y="145">数量</text><text x="194" y="124">需要</text><text x="194" y="28">供給</text><text x="34" y="68">均衡価格</text></svg>';

  L.c_econ = {
    goal: '需要と供給で価格が決まるしくみを図で説明でき、労働・金融・財政(税金)の基本的なしくみを理解できるようになる。',
    intro: '夏になるとアイスクリームがよく売れ、野菜が豊作だと値段が下がります。これは、買いたい量(需要)と売りたい量(供給)のバランスで価格が動いているからです。経済は、家計(わたしたちの家庭)・企業・政府の3つが、お金とものをやりとりして回っています。そのしくみを1つずつ見ていきましょう。',
    secs: [
      { h: '需要と供給で価格が決まる', t: '【需要】は買いたい量、【供給】は売りたい量です。\n価格が高いと、買いたい人は減り(需要が減る)、売りたい企業はふえます(供給がふえる)。だから、グラフにすると【需要曲線は右下がり】、【供給曲線は右上がり】になります。\n2つの曲線が交わる点で、買いたい量と売りたい量がつり合います。このときの価格を【均衡価格】といいます。\n需要が供給より多ければ品不足になって価格は上がり、供給が需要より多ければ売れ残って価格は下がります。このように、市場で価格が上下して需要と供給が調整されるしくみを【市場メカニズム】といいます。\nただし、1つの企業が市場を支配する【独占】の状態では、競争が起きず価格が不当に高くなるおそれがあるため、【独占禁止法】があり、【公正取引委員会】が監視しています。電気・水道などの【公共料金】は、国や地方公共団体が決定や認可をします。',
        fig: SUPPLY,
        ex: [{ q: 'ある年、キャベツが大豊作になった。キャベツの価格はどうなる?需要と供給の言葉を使って説明しよう。', steps: ['大豊作で、市場に出回るキャベツ(売りたい量=供給)がふえる。', '買いたい量(需要)はほとんど変わらない。', '供給が需要を上回るので売れ残りが出て、売るために価格が下がる。'], a: '供給がふえて需要を上回るため、価格は下がる。' }] },
      { h: '企業と労働', t: '企業の多くは【株式会社】です。株式を発行して多くの人から資金を集め、利益が出れば株主に【配当】を分けます。株主は、会社が倒産しても出資した額以上の責任は負いません(有限責任)。株主は株主総会で経営の方針を決めることに参加できます。\n働く人を守るため、【労働基準法】(労働時間は原則1日8時間・週40時間以内など)、【労働組合法】、【労働関係調整法】の【労働三法】があります。\n憲法は、労働者に【団結権・団体交渉権・団体行動権(争議権)】の【労働三権】を保障しています。1人では弱い立場の労働者が、団結して使用者と対等に話し合うためです。\n近年は、パートやアルバイトなどの非正規雇用の増加、長時間労働、仕事と生活の調和(ワーク・ライフ・バランス)が課題です。' },
      { h: '金融と日本銀行', t: 'お金に余裕のある人から足りない人へお金を融通することを【金融】といいます。銀行が預金を集めて企業などに貸し出すのが【間接金融】、企業が株式や社債を発行して直接お金を集めるのが【直接金融】です。\n日本の中央銀行である【日本銀行】には3つの役割があります。①紙幣(日本銀行券)を発行する【発券銀行】、②一般の銀行に貸し出しなどをする【銀行の銀行】、③政府のお金を出し入れする【政府の銀行】。\n日本銀行は、景気や物価を安定させるために【金融政策】を行います。中心は、銀行との間で国債などを売り買いする【公開市場操作】です。\n・不景気のとき:日銀が銀行から国債などを【買う】→ 銀行の資金がふえる → 金利が下がり、企業がお金を借りやすくなる → 景気が回復に向かう。\n・景気が過熱して物価が上がりすぎるとき:日銀が国債などを【売る】→ 銀行の資金が減る → 金利が上がる → 景気がおさえられる。' },
      { h: '財政と税金', t: '国や地方公共団体の経済活動を【財政】といいます。収入を歳入、支出を歳出といい、国の歳出でいちばん大きいのは【社会保障関係費】です。税金でたりない分は国債(国の借金)を発行して補っています。\n税金には、納める人と負担する人が同じ【直接税】(所得税・法人税など)と、ちがう【間接税】(消費税など)があります。\n所得税は、所得が多いほど高い税率をかける【累進課税】で、所得の差を小さくするはたらきがあります。一方、消費税は所得に関係なく同じ税率なので、所得の低い人ほど所得にしめる税の負担の割合が高くなる【逆進性】があります。\n政府も、不景気のときは公共事業をふやしたり減税したりし、好景気のときはその逆を行って、景気を安定させます(【財政政策】)。',
        ex: [{ q: '所得200万円の人と1000万円の人が、それぞれ1年間に100万円分の買い物をした。消費税10%の負担は、所得に対して何%ずつになる?', steps: ['2人とも消費税は 100万円×10%=10万円。', '所得200万円の人:10万÷200万=0.05 → 5%。', '所得1000万円の人:10万÷1000万=0.01 → 1%。', '所得の低い人ほど負担の割合が高い=逆進性。'], a: '所得200万円の人は5%、1000万円の人は1%(所得の低い人ほど負担の割合が高い)。' }] }
    ],
    terms: [['均衡価格', '需要量と供給量がつり合ったときの価格'], ['独占禁止法', '企業の独占を防ぎ、公正な競争を守る法律。公正取引委員会が運用'], ['労働三権', '団結権・団体交渉権・団体行動権'], ['公開市場操作', '日本銀行が国債などを売買して、出回るお金の量を調整すること'], ['累進課税', '所得が多いほど高い税率をかけるしくみ'], ['逆進性', '所得の低い人ほど、所得にしめる税負担の割合が高くなる性質']],
    miss: ['需要曲線と供給曲線の向き(右下がり・右上がり)を逆にする。', '不景気のときに日銀が国債を「売る」と思う(買ってお金をふやす)。', '消費税を直接税だと思う(納める人=店と、負担する人=消費者がちがう間接税)。'],
    sum: ['需要>供給なら価格は上がり、供給>需要なら下がる。', '需要曲線は右下がり、供給曲線は右上がり、交点が均衡価格。', '日本銀行は発券銀行・銀行の銀行・政府の銀行。', '不景気には日銀が国債を買い、政府は公共事業・減税。', '所得税は累進課税、消費税には逆進性。']
  };

  L.c_kokusai = {
    goal: '国家と国際社会のしくみ、国際連合(とくに安全保障理事会と拒否権)のはたらき、地球環境問題や国際協力の流れを説明できるようになる。',
    intro: '世界には190をこえる国があり、それぞれが自分の国のことを自分で決める権利(主権)をもっています。でも、紛争や地球温暖化のように、1つの国だけでは解決できない問題がたくさんあります。そこで国々は、国際連合などの場で話し合い、ルールをつくって協力しています。そのしくみと、うまくいかない理由の両方を知ることが大切です。',
    secs: [
      { h: '国家と国際社会のルール', t: '国家は、【主権・領域・国民】の3つの要素からなります。領域は領土・領海・領空です。\n主権をもつ国家どうしは、たがいに対等で、ほかの国から支配や干渉を受けません(主権平等・内政不干渉)。\n国どうしのルールを【国際法】といい、文書で約束した【条約】と、長い間の慣行がルールになった【国際慣習法】があります。国どうしの争いを裁く機関として、オランダのハーグに【国際司法裁判所】がありますが、裁判には原則として争っている両方の国の同意が必要です。' },
      { h: '国際連合のしくみ', t: '【国際連合(国連)】は、第二次世界大戦の反省から1945年に発足しました。本部はアメリカのニューヨークです。\n【総会】…すべての加盟国が参加し、1国1票で議決します。\n【安全保障理事会(安保理)】…世界の平和と安全の維持に主な責任をもちます。アメリカ・イギリス・フランス・ロシア・中国の5つの【常任理事国】と、任期2年の10の非常任理事国の15か国で構成されます。重要な議題(実質事項)は9か国以上の賛成で決まりますが、常任理事国が1か国でも反対すると決議できません。これを【拒否権】といいます。\n大国が反対する決議が成立しないので、大国どうしが対立すると、安保理が動けなくなるという問題があります。\nほかにも、教育・科学・文化の【UNESCO(ユネスコ)】、保健の【WHO(世界保健機関)】、子どもを支援する【UNICEF(ユニセフ)】、難民を保護する【UNHCR】などが活動しています。紛争地域で停戦の監視などを行う活動を【PKO(平和維持活動)】といいます。',
        ex: [{ q: '安保理で、ある決議案の採決をしたところ、15か国中12か国が賛成し、3か国が反対した。反対した3か国のうち1か国はフランスだった。この決議案は成立する?', steps: ['実質事項は、15か国中9か国以上の賛成が必要 → 12か国なので条件は満たしている。', 'ただし、常任理事国が1か国でも反対すると成立しない(拒否権)。', 'フランスは常任理事国なので、その反対は拒否権の行使になる。'], a: '成立しない(常任理事国のフランスが反対し、拒否権が行使されたため)。' }] },
      { h: '地域統合と南北問題', t: '近い国どうしが経済などで協力を深める【地域統合】が進んでいます。ヨーロッパの【EU(ヨーロッパ連合)】、東南アジアの【ASEAN(東南アジア諸国連合)】、アジア・太平洋地域の【APEC(アジア太平洋経済協力)】などです。\n先進国(多くは北半球)と発展途上国(多くは南側)の経済格差の問題を【南北問題】といいます。さらに、発展途上国の中でも、資源の豊富な国や工業化に成功した国と、そうでない国との格差が広がっています(【南南問題】)。\n日本は、発展途上国に資金や技術を提供する【ODA(政府開発援助)】を行い、JICA(国際協力機構)の青年海外協力隊なども活動しています。政府ではない民間の団体【NGO(非政府組織)】も、国際協力で大きな役割を果たしています。' },
      { h: '地球環境問題と平和への取り組み', t: '地球温暖化・酸性雨・砂漠化・熱帯林の減少などの地球環境問題は、国境をこえた協力が必要です。\n1992年、ブラジルのリオデジャネイロで【国連環境開発会議(地球サミット)】が開かれました。\n1997年の【京都議定書】では、【先進国】に温室効果ガスの削減を義務づけました。しかし、排出量の多い発展途上国に削減義務がないことなどが課題でした。\n2015年の【パリ協定】では、発展途上国をふくむ【すべての参加国】が、自分で削減目標を立てて取り組むことになりました。産業革命前からの気温上昇を2度より十分低くおさえ、1.5度におさえる努力をすることが目標です。\n平和の面では、核兵器の広がりを防ぐ【核拡散防止条約(NPT)】や、核兵器の開発・保有・使用などを禁止する【核兵器禁止条約】(2017年採択)があります。日本は唯一の戦争被爆国として、【非核三原則】(持たず・つくらず・持ちこませず)をかかげています。',
        ex: [{ q: '京都議定書とパリ協定のいちばん大きなちがいは何?', steps: ['京都議定書(1997年):温室効果ガスの削減を義務づけられたのは先進国だけ。', 'パリ協定(2015年):発展途上国をふくむすべての参加国が、それぞれ削減目標を立てて取り組む。', 'ちがいは「だれが取り組むか」。'], a: '京都議定書は先進国にだけ削減を義務づけたが、パリ協定は発展途上国をふくむすべての参加国が削減目標を立てて取り組むこと。' }] }
    ],
    terms: [['主権', 'ほかの国から支配や干渉を受けず、自分の国のことを決める権利'], ['安全保障理事会', '国連で平和と安全の維持に主な責任をもつ機関。15か国で構成'], ['拒否権', '常任理事国が1か国でも反対すると、重要な決議ができない権限'], ['PKO', '国連の平和維持活動。紛争地域での停戦監視など'], ['南北問題', '先進国と発展途上国の経済格差の問題'], ['パリ協定', '2015年採択。すべての参加国が温室効果ガス削減に取り組む枠組み']],
    miss: ['常任理事国に日本やドイツをふくめてしまう(米・英・仏・露・中の5か国)。', '9か国以上が賛成すれば必ず決議できると思う(常任理事国の拒否権がある)。', '京都議定書で発展途上国にも削減義務があったと思う(先進国のみ)。'],
    sum: ['国家は主権・領域・国民の3要素。', '国連の安保理は常任理事国5か国+非常任理事国10か国。常任理事国には拒否権。', '地域統合(EU・ASEANなど)と、南北問題・南南問題。', '温暖化対策は京都議定書(1997・先進国のみ)からパリ協定(2015・すべての国)へ。']
  };

  // ===== 公共・政治経済 =====
  L.c_h3 = {
    goal: '民主政治の原理、契約と消費者の権利、為替相場(円高・円安)、金融政策と財政・社会保障のしくみを、具体的な数字や場面で説明できるようになる。',
    intro: '「公共」は、18歳で成年になるみなさんが、主権者・消費者・働く人として社会に参加するための科目です。ニュースでよく聞く「円安で物価が上がる」「日銀が金利を上げる」なども、しくみが分かれば自分の生活とのつながりが見えてきます。混乱しやすいところは、必ず具体的な数字で確かめながら読みましょう。',
    secs: [
      { h: '民主政治の原理と法の支配', t: '【社会契約説】…国家は、人々が自分の権利を守るために契約(合意)してつくったものだ、という考え方。ロックは、政府が人々の権利をおかすなら、人々は政府に抵抗し、政府をつくりかえることができる(抵抗権)と説き、アメリカ独立宣言などに影響を与えました。ルソーは、人々が直接政治に参加する人民主権を説きました。\n【法の支配】…権力者もふくめ、すべての人が、人権を守るための正しい法に従わなければならないという考え方。権力者が思うままに支配する「人の支配」と対立します。\n【権力分立】…モンテスキューが説いた三権分立。権力を分けてたがいに抑制させ、人権を守ります。\nこれらの考え方の土台の上に、日本国憲法の国民主権・基本的人権の尊重・平和主義が成り立っています。' },
      { h: '契約と消費者の権利', t: '【契約】は、たがいの合意(意思表示の一致)で成立します。口約束でも、原則として契約は成立します。成立した契約は、一方的にやめることはできません。\n2022年4月から【成年年齢が18歳】に引き下げられました。成年になると、親の同意なしで契約ができるかわりに、未成年者であることを理由にした契約の取り消しができなくなります。\n消費者を守るしくみ:\n・【クーリング・オフ】…訪問販売や電話勧誘販売などで契約した場合、契約書面を受け取った日から8日以内なら、無条件で契約を解除できる(マルチ商法などは20日以内)。店に自分で行って買った場合は対象外。\n・【製造物責任法(PL法)】…製品の欠陥で被害を受けた場合、製造者に過失がなくても損害賠償を求められる。\n・【消費者契約法】…うその説明などで結んだ契約を取り消せる。',
        ex: [{ q: '18歳の高校生が、自宅に来た訪問販売員から教材を買う契約をし、契約書面を受け取った。5日後に解約したくなった。どうすればよい?', steps: ['18歳は成年なので、「未成年だから」という理由での取り消しはできない。', 'しかし訪問販売なので、クーリング・オフの対象になる。', '書面を受け取った日から8日以内(今は5日後)なので、まだ期間内。', 'クーリング・オフは書面(はがきなど)または電磁的記録(メールなど)で通知する。'], a: 'クーリング・オフの期間(8日以内)なので、書面やメールなどで通知すれば、無条件で契約を解除できる。' }] },
      { h: '為替相場:円高と円安', t: '円と外国のお金を交換するときの比率を【為替相場(為替レート)】といいます。\n【円高】…円の価値が上がること。1ドル=100円 → 1ドル=80円 のように、【少ない円で1ドルと交換できる】ようになる。\n【円安】…円の価値が下がること。1ドル=100円 → 1ドル=120円 のように、1ドルを手に入れるのにより多くの円が必要になる。\n「数字が小さくなるのに円高」と混乱しやすいので、必ず「1ドルを買うのに何円必要か」で考えましょう。\n円高の影響:輸入品が安くなる → 輸入企業や海外旅行をする人に有利。日本製品が海外で値上がりする → 輸出企業には不利。\n円安の影響:その逆。輸出企業には有利だが、輸入品(エネルギー・食料など)が値上がりし、国内の物価を押し上げる。\n為替相場は、円を買いたい人が多ければ円高、円を売りたい人が多ければ円安に動きます。',
        ex: [{ q: '1ドル=100円から1ドル=80円になった。日本の会社が国内で100万円の製品をアメリカに輸出するとき、アメリカでの価格(ドル)はどう変わる?', steps: ['1ドル=100円のとき:100万÷100=1万ドル。', '1ドル=80円のとき:100万÷80=1万2500ドル。', 'アメリカでの価格が2500ドル上がり、売れにくくなる。', '少ない円で1ドルと交換できるようになった=円高。'], a: '1万ドルから1万2500ドルに値上がりする(円高で輸出に不利になる)。' }] },
      { h: '金融政策・財政・社会保障', t: '【日本銀行】は、発券銀行・銀行の銀行・政府の銀行として、物価の安定を目的に【金融政策】を行います。中心は、国債などを売買して出回るお金の量や金利を調整する【公開市場操作】です。不景気やデフレ(物価が下がり続けること)のときは国債などを買って【金融緩和】、景気が過熱しインフレ(物価が上がり続けること)のときは売って【金融引き締め】を行います。\n【財政】には3つの機能があります。①道路や警察など、市場にまかせると十分に供給されないものを提供する【資源配分】、②累進課税や社会保障で所得の差を小さくする【所得の再分配】、③景気を安定させる【景気の安定化】(公共事業の増減や減税・増税)。\n【社会保障】は、憲法25条の生存権を実現するしくみで、4つの柱があります。①【社会保険】(医療・年金・雇用・労災・介護保険)、②【公的扶助】(生活保護)、③【社会福祉】(高齢者・障がい者・子どもなどへの支援)、④【公衆衛生】(感染症の予防など)。少子高齢化で、社会保障を支える財源の確保が大きな課題です。',
        ex: [{ q: '景気が悪く、物価が下がり続けている。日本銀行と政府がとる政策の例を1つずつ答えよう。', steps: ['日本銀行:世の中に出回るお金をふやしたい → 銀行から国債などを買う(金融緩和)。', 'その結果、金利が下がり、企業がお金を借りて投資しやすくなる。', '政府:需要をふやしたい → 公共事業をふやす、または減税する(財政政策)。'], a: '日本銀行は国債などを買って金融緩和を行い、政府は公共事業をふやしたり減税したりする。' }] }
    ],
    terms: [['法の支配', '権力者もふくめ、すべての人が正しい法に従うという考え方'], ['クーリング・オフ', '訪問販売などの契約を、一定期間内なら無条件で解除できる制度'], ['円高', '円の価値が上がること。1ドル=100円 → 80円など'], ['金融緩和', '日本銀行が国債などを買い、出回るお金をふやして金利を下げる政策'], ['所得の再分配', '累進課税や社会保障で、所得の格差を小さくする財政の機能'], ['社会保険', '加入者が保険料を出し合い、病気・老後・失業などに備える制度']],
    miss: ['1ドル=100円 → 80円を、数字が減ったから「円安」と答える(少ない円で買えるので円高)。', '円高が輸出企業に有利だと思う(海外での価格が上がるので不利)。', 'クーリング・オフが、店で自分で買った商品にも使えると思う(訪問販売などが対象)。', '社会保険と公的扶助を混同する(保険料を出し合うのが社会保険、生活保護が公的扶助)。'],
    sum: ['法の支配・社会契約説・権力分立が民主政治の土台。', '成年年齢は18歳。訪問販売などは8日以内ならクーリング・オフ。', '円高=少ない円で1ドル。輸入に有利、輸出に不利。', '不景気には日銀が金融緩和、政府は公共事業・減税。', '社会保障の4本柱:社会保険・公的扶助・社会福祉・公衆衛生。']
  };
})(WPS.LESSONS);
